import { useState, useEffect, lazy, Suspense } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
const ReactQueryDevtoolsLazy = lazy(() =>
  import('@tanstack/react-query-devtools').then((m) => ({ default: m.ReactQueryDevtools })),
);
const KnowledgeBasePage = lazy(() =>
  import('./pages/KnowledgeBasePage').then((m) => ({ default: m.KnowledgeBasePage })),
);
const SettingsPage = lazy(() =>
  import('./pages/SettingsPage').then((m) => ({ default: m.SettingsPage })),
);
const MCPPage = lazy(() => import('./pages/MCPPage').then((m) => ({ default: m.MCPPage })));
const EmbeddingsPage = lazy(() =>
  import('./pages/EmbeddingsPage').then((m) => ({ default: m.EmbeddingsPage })),
);
const EvalPage = lazy(() => import('./pages/EvalPage').then((m) => ({ default: m.EvalPage })));
const OnboardingPage = lazy(() =>
  import('./pages/OnboardingPage').then((m) => ({ default: m.OnboardingPage })),
);
import { MainLayout } from './components/layout/MainLayout';
import { ThemeProvider } from './contexts/ThemeContext';
import { ToastProvider } from './contexts/ToastContext';
import { ToastProvider as FeaturesToastProvider } from './features/ui/components/ToastProvider';
import { SettingsProvider, useSettings } from './contexts/SettingsContext';
import { TooltipProvider } from './features/ui/primitives/tooltip';
const ProjectPage = lazy(() =>
  import('./pages/ProjectPage').then((m) => ({ default: m.ProjectPage })),
);
import { DisconnectScreenOverlay } from './components/DisconnectScreenOverlay';
import { ErrorBoundaryWithBugReport } from './components/bug-report/ErrorBoundaryWithBugReport';
import { MigrationBanner } from './components/ui/MigrationBanner';
import { serverHealthService } from './services/serverHealthService';
import { useMigrationStatus } from './hooks/useMigrationStatus';

// Create a client with optimized settings for our polling use case
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      // Keep data fresh for 2 seconds by default
      staleTime: 2000,
      // Cache data for 5 minutes
      gcTime: 5 * 60 * 1000,
      // Retry failed requests 3 times
      retry: 3,
      // Refetch on window focus
      refetchOnWindowFocus: true,
      // Don't refetch on reconnect by default (we handle this manually)
      refetchOnReconnect: false,
    },
    mutations: {
      // Retry mutations once on failure
      retry: 1,
    },
  },
});

const AppRoutes = () => {
  const { projectsEnabled } = useSettings();

  return (
    <Routes>
      <Route path="/" element={<KnowledgeBasePage />} />
      <Route path="/onboarding" element={<OnboardingPage />} />
      <Route path="/settings" element={<SettingsPage />} />
      <Route path="/mcp" element={<MCPPage />} />
      <Route path="/embeddings" element={<EmbeddingsPage />} />
      <Route path="/eval" element={<EvalPage />} />
      {projectsEnabled ? (
        <>
          <Route path="/projects" element={<ProjectPage />} />
          <Route path="/projects/:projectId" element={<ProjectPage />} />
        </>
      ) : (
        <Route path="/projects" element={<Navigate to="/" replace />} />
      )}
    </Routes>
  );
};

const AppContent = () => {
  const [disconnectScreenActive, setDisconnectScreenActive] = useState(false);
  const [disconnectScreenDismissed, setDisconnectScreenDismissed] = useState(false);
  const [disconnectScreenSettings, setDisconnectScreenSettings] = useState({
    enabled: true,
    delay: 10000
  });
  const [migrationBannerDismissed, setMigrationBannerDismissed] = useState(false);
  const migrationStatus = useMigrationStatus();

  useEffect(() => {
    // Load initial settings
    const settings = serverHealthService.getSettings();
    setDisconnectScreenSettings(settings);

    // Stop any existing monitoring before starting new one to prevent multiple intervals
    serverHealthService.stopMonitoring();

    // Start health monitoring
    serverHealthService.startMonitoring({
      onDisconnected: () => {
        if (!disconnectScreenDismissed) {
          setDisconnectScreenActive(true);
        }
      },
      onReconnected: () => {
        setDisconnectScreenActive(false);
        setDisconnectScreenDismissed(false);
        // Refresh the page to ensure all data is fresh
        window.location.reload();
      }
    });

    return () => {
      serverHealthService.stopMonitoring();
    };
  }, [disconnectScreenDismissed]);

  const handleDismissDisconnectScreen = () => {
    setDisconnectScreenActive(false);
    setDisconnectScreenDismissed(true);
  };

  return (
    <>
      <Router>
        <ErrorBoundaryWithBugReport>
          <MainLayout>
            {/* Migration Banner - shows when backend is up but DB schema needs work */}
            {migrationStatus.migrationRequired && !migrationBannerDismissed && (
              <MigrationBanner
                message={migrationStatus.message || "Database migration required"}
                onDismiss={() => setMigrationBannerDismissed(true)}
              />
            )}
            <Suspense fallback={<div className="p-4 text-sm text-zinc-500">Loading…</div>}>
              <AppRoutes />
            </Suspense>
          </MainLayout>
        </ErrorBoundaryWithBugReport>
      </Router>
      <DisconnectScreenOverlay
        isActive={disconnectScreenActive && disconnectScreenSettings.enabled}
        onDismiss={handleDismissDisconnectScreen}
      />
    </>
  );
};

export function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <ToastProvider>
          <FeaturesToastProvider>
            <TooltipProvider>
              <SettingsProvider>
                <AppContent />
              </SettingsProvider>
            </TooltipProvider>
          </FeaturesToastProvider>
        </ToastProvider>
      </ThemeProvider>
      {import.meta.env.VITE_SHOW_DEVTOOLS === 'true' && (
        <Suspense fallback={null}>
          <ReactQueryDevtoolsLazy initialIsOpen={false} />
        </Suspense>
      )}
    </QueryClientProvider>
  );
}

import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import { AGENTS, type Agent } from "./registry";

type AgentState = {
  agents: Agent[];
  selectedAgentId: string;
  setSelectedAgentId: (id: string) => void;
  selectedAgent: Agent;
};

const AgentCtx = createContext<AgentState | null>(null);

const DEFAULT_ID = AGENTS[0]?.id ?? "profesora-maria";
const KEY = "archon.selectedAgentId";

export const AgentProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [selectedAgentId, setSelectedAgentId] = useState<string>(() => {
    try {
      return localStorage.getItem(KEY) ?? DEFAULT_ID;
    } catch {
      return DEFAULT_ID;
    }
  });


  useEffect(() => {
    try {
      localStorage.setItem(KEY, selectedAgentId);
    } catch {
      // non-critical: ignore storage write failures (e.g., private mode)
      void 0;
    }
  }, [selectedAgentId]);


  const selectedAgent = useMemo(
    () => AGENTS.find(a => a.id === selectedAgentId) ?? AGENTS[0] ?? { id: DEFAULT_ID, label: "Default" },
    [selectedAgentId]
  );

  const value = useMemo<AgentState>(
    () => ({
      agents: AGENTS,
      selectedAgentId,
      setSelectedAgentId,
      selectedAgent,
    }),
    [selectedAgentId, selectedAgent]
  );

  return <AgentCtx.Provider value={value}>{children}</AgentCtx.Provider>;
};

export const useAgentState = (): AgentState => {
  const ctx = useContext(AgentCtx);
  if (!ctx) throw new Error("useAgentState must be used within AgentProvider");
  return ctx;
};

import React, { useEffect, useState, useRef } from 'react';
import { Send, User, WifiOff, RefreshCw } from 'lucide-react';
import { ArchonLoadingSpinner, EdgeLitEffect } from '../animations/Animations';
import { agentChatService, ChatMessage } from '../../services/agentChatService';
import { knowledgeBaseService } from '../../services/knowledgeBaseService';
import { AgentSwitcher } from '../../agents/AgentSwitcher';
import { useAgentState } from '../../agents/AgentContext';
import { getAgentTypeFor } from '../../agents/registry';

/**
 * Props for the ArchonChatPanel component
 */
interface ArchonChatPanelProps {
  'data-id'?: string;
}
/**
 * ArchonChatPanel - A chat interface for the Archon AI assistant
 *
 * This component provides a resizable chat panel with message history,
 * loading states, and input functionality connected to real AI agents.
 */
export const ArchonChatPanel: React.FC<ArchonChatPanelProps> = props => {
  const { selectedAgentId, selectedAgent } = useAgentState();
  // State for messages, session, and other chat functionality
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [isInitialized, setIsInitialized] = useState(false);
  // State for input field, panel width, loading state, and dragging state
  const [inputValue, setInputValue] = useState('');
  const [width, _setWidth] = useState(416); // Default width - increased by 30% from 320px
  const [isTyping, _setIsTyping] = useState(false);
  const [isDragging, setIsDragging] = useState(false);
  const [connectionError, setConnectionError] = useState<string | null>(null);
  const [streamingMessage, _setStreamingMessage] = useState<string>('');
  const [isStreaming, _setIsStreaming] = useState(false);

  // Add connection status state
  const [connectionStatus, setConnectionStatus] = useState<'online' | 'offline' | 'connecting'>('connecting');
  const [isReconnecting, setIsReconnecting] = useState(false);

  // No agent switching - always use RAG

  // Refs for DOM elements
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const dragHandleRef = useRef<HTMLDivElement>(null);
  const chatPanelRef = useRef<HTMLDivElement>(null);
  const sessionIdRef = useRef<string | null>(null);
  const ensuredPydanticKBRef = useRef<boolean>(false);
  /**
   * Initialize chat session and connection
   */
  const initializeChat = React.useCallback(async () => {
    try {
      setConnectionStatus('connecting');

      // Yield to next frame to avoid initialization race conditions
      await new Promise(resolve => requestAnimationFrame(resolve));

      // Create a new chat session
      try {
          const agentType = getAgentTypeFor(selectedAgentId);
          console.log(`[CHAT PANEL] Creating session with agentType: "${agentType}" for agentId: ${selectedAgentId}`);
          const { session_id } = await agentChatService.createSession(agentType);
          console.log(`[CHAT PANEL] Session created with ID: ${session_id}`);
          setSessionId(session_id);
          sessionIdRef.current = session_id;

          // Ensure Pydantic docs are available when using Pydantic AI (best-effort)
          if (selectedAgentId === 'pydantic-ai' && !ensuredPydanticKBRef.current) {
            ensuredPydanticKBRef.current = true;
            try {
              const items = await knowledgeBaseService.getKnowledgeItems({ search: 'Pydantic Documentation - Llms-Full.Txt', per_page: 5 });
              const found = items.items?.some(i => i.title?.toLowerCase().includes('pydantic') && i.title.toLowerCase().includes('llms-full'));
              if (!found) {
                await knowledgeBaseService.crawlUrl({
                  url: 'https://ai.pydantic.dev/llms-full.txt',
                  knowledge_type: 'technical',
                  tags: ['pydantic', 'llmstxt'],
                  max_depth: 0,
                });
              }
            } catch (e) {
              console.warn('Pydantic KB ensure failed (non-fatal):', e);
            }
          }

          // Load initial chat history
          try {
            const history = await agentChatService.getChatHistory(session_id);
            console.log(`[CHAT PANEL] Loaded chat history:`, history);
            setMessages(history || []);
          } catch (error) {
            console.error('Failed to load chat history:', error);
            // Initialize with empty messages if history can't be loaded
            setMessages([]);
          }

          // Start polling for new messages (will fail gracefully if backend is down)
          try {
            await agentChatService.streamMessages(
              session_id,
              (message: ChatMessage) => {
                setMessages(prev => {
                  // Check if message already exists to prevent duplicates
                  if (prev.some(msg => msg.id === message.id)) {
                    return prev;
                  }
                  return [...prev, message];
                });
                setConnectionError(null); // Clear any previous errors on successful message
                setConnectionStatus('online');
              },
              (error: Error) => {
                console.error('Message streaming error:', error);
                setConnectionStatus('offline');
                setConnectionError('Chat service is offline. Messages will not be received.');
              }
            );
          } catch (error) {
            console.error('Failed to start message streaming:', error);
            // Continue anyway - the chat will work in offline mode
          }

          setIsInitialized(true);
          setConnectionStatus('online');
          setConnectionError(null);
        } catch (error) {
          console.error('Failed to initialize chat session:', error);
          if (error instanceof Error && error.message.includes('not available')) {
            setConnectionError('Agent chat service is disabled. Enable it in docker-compose to use this feature.');
          } else {
            setConnectionError('Failed to initialize chat. Server may be offline.');
          }
          setConnectionStatus('offline');
        }

      } catch (error) {
        console.error('Failed to initialize chat:', error);
        if (error instanceof Error && error.message.includes('not available')) {
          setConnectionError('Agent chat service is disabled. Enable it in docker-compose to use this feature.');
        } else {
          setConnectionError('Failed to connect to agent. Server may be offline.');
        }
        setConnectionStatus('offline');
      }
    }, [selectedAgentId]);

  // Initialize on mount and when explicitly requested
  useEffect(() => {
    if (!isInitialized) {
      initializeChat();
    }
  }, [isInitialized, initializeChat]);

  // Re-initialize session when selected agent changes
  const prevAgentIdRef = React.useRef<string | null>(null);
  useEffect(() => {
    if (prevAgentIdRef.current && prevAgentIdRef.current !== selectedAgentId) {
      if (sessionIdRef.current) {
        agentChatService.stopStreaming(sessionIdRef.current);
      }
      setMessages([]);
      setSessionId(null);
      setIsInitialized(false);
      setConnectionStatus('connecting');
      initializeChat();
    }
    prevAgentIdRef.current = selectedAgentId;
  }, [selectedAgentId, initializeChat]);

  // Cleanup effect - only on unmount
  useEffect(() => {
    return () => {
      if (sessionIdRef.current) {
        console.log('[CHAT PANEL] Component unmounting, cleaning up session:', sessionIdRef.current);
        // Stop streaming messages when component unmounts
        agentChatService.stopStreaming(sessionIdRef.current);
      }
    };
  }, []); // Empty deps = only on unmount

  /**
   * Handle resizing of the chat panel via drag
   */
  useEffect(() => {
    // Handler for mouse movement during drag
    const handleMouseMove = (e: MouseEvent) => {
      if (isDragging && chatPanelRef.current) {
        const containerRect = chatPanelRef.current.parentElement?.getBoundingClientRect();
        if (containerRect) {
          // Calculate new width based on mouse position (from right edge of screen)
          const newWidth = window.innerWidth - e.clientX;
          // Set min and max width constraints
          if (newWidth >= 280 && newWidth <= 600) {
            setWidth(newWidth);
          }
        }
      }
    };
    // Handler for mouse up to end dragging
    const handleMouseUp = () => {
      setIsDragging(false);
      document.body.style.cursor = 'default';
      document.body.style.userSelect = 'auto';
    };
    // Add event listeners when dragging
    if (isDragging) {
      document.addEventListener('mousemove', handleMouseMove);
      document.addEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = 'ew-resize';
      document.body.style.userSelect = 'none'; // Prevent text selection while dragging
    }
    // Clean up event listeners
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);
  /**
   * Handler for starting the drag operation
   */
  const handleDragStart = (e: React.MouseEvent) => {
    e.preventDefault();
    setIsDragging(true);
  };
  /**
   * Auto-scroll to the bottom when messages change
   */
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({
      behavior: 'smooth'
    });
  }, [messages, isTyping, streamingMessage]);
  /**
   * Handle sending a new message to the agent
   */
  const handleSendMessage = async () => {
    if (!inputValue.trim() || !sessionId) return;

    try {
      // Build context based on selected agent
      const context = (() => {
        if (selectedAgentId === 'profesora-maria') {
          return {
            student_level: 'intermediate',
            conversation_mode: 'casual',
            // Prefer concise bilingual read-out
            response_style: 'minimal',
            include_translation: true,
            include_corrections: true,
            include_grammar_notes: false,
            include_vocabulary: true,
            include_cultural_notes: false,
            include_encouragement: true,
            include_next_topic: true,
            max_reply_sentences: 1,
            reading_mode: true,
          };
        }
        if (selectedAgentId === 'pydantic-ai') {
          return {
            domain: 'pydantic-ai',
            knowledge_source: 'llmstxt',
            dataset_hint: 'Pydantic Documentation - Llms-Full.Txt',
            source_filter: 'pydantic|ai.pydantic.dev|llms-full|ai-agent-mastery',
          };
        }
        return {};
      })();

      // Send message to agent via service
      await agentChatService.sendMessage(sessionId, {
        message: inputValue.trim(),
        context,
        agentId: selectedAgentId,
      });
      setInputValue('');
      setConnectionError(null);
    } catch (error) {
      console.error('Failed to send message:', error);
      setConnectionError('Failed to send message. Please try again.');
    }
  };
  /**
   * Format timestamp for display in messages
   */
  const formatTime = (timestamp: string | Date) => {
    const date = typeof timestamp === 'string' ? new Date(timestamp) : timestamp;
    return date.toLocaleTimeString([], {
      hour: '2-digit',
      minute: '2-digit'
    });
  };
  const placeholderForAgent = () => {
    const label = selectedAgent?.label || 'Agent';
    return `Message ${label}...`;
  };
  /**
   * Handle manual reconnection
   */
  const handleReconnect = async () => {
    if (!sessionId || isReconnecting) return;

    setIsReconnecting(true);
    setConnectionStatus('connecting');
    setConnectionError('Attempting to reconnect...');

    try {
      const success = await agentChatService.manualReconnect(sessionId);
      if (success) {
        setConnectionError(null);
        setConnectionStatus('online');
      } else {
        setConnectionError('Reconnection failed. Server may still be offline.');
        setConnectionStatus('offline');
      }
    } catch (error) {
      console.error('Manual reconnection failed:', error);
      setConnectionError('Reconnection failed. Please try again later.');
      setConnectionStatus('offline');
    } finally {
      setIsReconnecting(false);
    }
  };
  return (
    <div ref={chatPanelRef} className="h-full flex flex-col relative" style={{
      width: `${width}px`
    }} data-id={props['data-id']}>
      {/* Drag handle for resizing */}
      <div ref={dragHandleRef} className={`absolute left-0 top-0 w-1.5 h-full cursor-ew-resize z-20 ${isDragging ? 'bg-blue-500/50' : 'bg-transparent hover:bg-blue-500/30'} transition-colors duration-200`} onMouseDown={handleDragStart} />
      {/* Main panel with glassmorphism */}
      <div className="h-full flex flex-col relative backdrop-blur-md bg-gradient-to-b from-white/80 to-white/60 dark:from-white/10 dark:to-black/30 border-l border-blue-200 dark:border-blue-500/30">
        {/* Edgelit glow effect */}
        <EdgeLitEffect color="blue" />
        {/* Header gradient background */}
        <div className="absolute top-0 left-0 right-0 h-16 bg-gradient-to-b from-blue-100 to-white dark:from-blue-500/20 dark:to-blue-500/5 rounded-t-md pointer-events-none"></div>
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-zinc-800/80">
          <div className="flex flex-col gap-2">
            <div className="flex items-center gap-3">
              {/* Archon Logo - No animation in header */}
              <div className="relative w-8 h-8 flex items-center justify-center">
                <img src="/logo-neon.png" alt="Archon" className="w-6 h-6 z-10 relative" />
              </div>
              <AgentSwitcher label="Agent" />
            </div>
          </div>

          {/* Connection status and controls */}
          <div className="flex items-center gap-2">
            {/* Connection status indicator */}
            {connectionStatus === 'offline' && (
              <div className="flex items-center gap-2">
                <div className="flex items-center text-xs text-red-500 bg-red-100/80 dark:bg-red-900/30 px-2 py-1 rounded">
                  <WifiOff className="w-3 h-3 mr-1" />
                  Chat Offline
                </div>
                <button
                  onClick={handleReconnect}
                  disabled={isReconnecting}
                  className="flex items-center gap-1 text-xs text-blue-600 hover:text-blue-700 bg-blue-100/80 hover:bg-blue-200/80 dark:bg-blue-900/30 dark:hover:bg-blue-800/40 px-2 py-1 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  <RefreshCw className={`w-3 h-3 ${isReconnecting ? 'animate-spin' : ''}`} />
                  {isReconnecting ? 'Connecting...' : 'Reconnect'}
                </button>
              </div>
            )}

            {connectionStatus === 'connecting' && (
              <div className="text-xs text-blue-500 bg-blue-100/80 dark:bg-blue-900/30 px-2 py-1 rounded">
                <div className="flex items-center">
                  <RefreshCw className="w-3 h-3 mr-1 animate-spin" />
                  Connecting...
                </div>
              </div>
            )}

            {connectionStatus === 'online' && !connectionError && (
              <div className="text-xs text-green-600 bg-green-100/80 dark:bg-green-900/30 px-2 py-1 rounded">
                <div className="flex items-center">
                  <div className="w-2 h-2 bg-green-500 rounded-full mr-1" />
                  Online
                </div>
              </div>
            )}

            {/* Error message overlay */}
            {connectionError && connectionStatus !== 'offline' && (
              <div className="text-xs text-orange-600 bg-orange-100/80 dark:bg-orange-900/30 px-2 py-1 rounded">
                {connectionError}
              </div>
            )}
          </div>
        </div>
        {/* Messages area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-gray-50/50 dark:bg-transparent">
          {messages.map(message => (
            <div key={message.id} className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`
                max-w-[80%] rounded-lg p-3 
                ${message.sender === 'user' 
                  ? 'bg-purple-100/80 dark:bg-purple-500/20 border border-purple-200 dark:border-purple-500/30 ml-auto' 
                  : 'bg-blue-100/80 dark:bg-blue-500/20 border border-blue-200 dark:border-blue-500/30 mr-auto'}
              `}>
                <div className="flex items-center mb-1">
                  {message.sender === 'agent' ? (
                    <div className="w-4 h-4 mr-1 flex items-center justify-center">
                      <img src="/logo-neon.png" alt="Archon" className="w-full h-full" />
                    </div>
                  ) : (
                    <User className="w-4 h-4 text-purple-500 mr-1" />
                  )}
                  <span className="text-xs text-gray-500 dark:text-zinc-400">
                    {formatTime(message.timestamp)}
                  </span>
                </div>
                <div className="text-gray-800 dark:text-white text-sm whitespace-pre-wrap">
                  {/* For RAG responses, handle markdown-style formatting */}
                  {message.agent_type === 'rag' && message.sender === 'agent' ? (
                    <div className="prose prose-sm dark:prose-invert max-w-none">
                      {message.content.split('\n').map((line, idx) => {
                        // Handle bold text
                        const boldRegex = /\*\*(.*?)\*\*/g;
                        const parts = line.split(boldRegex);

                        return (
                          <div key={idx}>
                            {parts.map((part, partIdx) => 
                              partIdx % 2 === 1 ? (
                                <strong key={partIdx}>{part}</strong>
                              ) : (
                                <span key={partIdx}>{part}</span>
                              )
                            )}
                          </div>
                        );
                      })}
                    </div>
                  ) : (
                    message.content
                  )}
                </div>
              </div>
            </div>
          ))}
          {/* Streaming message */}
          {isStreaming && streamingMessage && (
            <div className="flex justify-start">
              <div className="max-w-[80%] bg-blue-100/80 dark:bg-blue-500/20 border border-blue-200 dark:border-blue-500/30 mr-auto rounded-lg p-3">
                <div className="flex items-center mb-1">
                  <div className="w-4 h-4 mr-1 flex items-center justify-center">
                    <img src="/logo-neon.png" alt="Archon" className="w-full h-full" />
                  </div>
                  <span className="text-xs text-gray-500 dark:text-zinc-400">
                    {formatTime(new Date())}
                  </span>
                  <div className="ml-2 w-1 h-1 bg-blue-500 rounded-full animate-pulse" />
                </div>
                <p className="text-gray-800 dark:text-white text-sm whitespace-pre-wrap">
                  {streamingMessage}
                </p>
              </div>
            </div>
          )}

          {/* Typing indicator */}
          {(isTyping && !isStreaming) && (
            <div className="flex justify-start">
              <div className="max-w-[80%] mr-auto flex items-center justify-center py-4">
                <ArchonLoadingSpinner size="md" />
