                    <option value="en-US">English (US)</option>
                  </select>
                </div>
                <div>
                  <label className="flex items-center gap-2 text-xs text-gray-700 dark:text-gray-200">
                    <input
                      type="checkbox"
                      checked={continuousDictation}
                      onChange={(e) => setContinuousDictation(e.target.checked)}
                    />
                    Continuous dictation (beta)
                  </label>
                </div>
                {continuousDictation && (
                  <div>
                    <div className="flex items-center justify-between text-xs font-medium text-gray-700 dark:text-gray-200 mb-1">
                      <span>Silence timeout</span>
                      <span className="opacity-70">{silenceTimeoutMs} ms</span>
                    </div>
                    <input
                      type="range"
                      min={300}
                      max={3000}
                      step={50}
                      value={silenceTimeoutMs}
                      onChange={(e) => setSilenceTimeoutMs(parseInt(e.target.value, 10))}
                      className="w-full"
                    />
                  </div>
                )}
                    <div>
                      <div className="flex items-center justify-between text-xs font-medium text-gray-700 dark:text-gray-200 mb-1">
                        <span>ASR confidence</span>
                        <span className="opacity-70">{confidenceThreshold.toFixed(2)}</span>
                      </div>
                      <input
                        type="range"
                        min={0}
                        max={1}
                        step={0.01}
                        value={confidenceThreshold}
                        onChange={(e) => setConfidenceThreshold(parseFloat(e.target.value))}
                        className="w-full"
                      />
                    </div>
                  </div>
                  <Popover.Arrow className="fill-white dark:fill-zinc-900" />
                </Popover.Content>
              </Popover.Portal>
            </Popover.Root>
          )}
        </div>
      </div>

      {/* Connection status */}
      {connectionError && (
        <div className="p-2 bg-red-100 dark:bg-red-900/30 border-b border-red-200 dark:border-red-800">
          <p className="text-red-700 dark:text-red-400 text-sm">{connectionError}</p>
        </div>
      )}

      {/* Voice error */}
      {voiceError && (
        <div className="p-2 bg-yellow-100 dark:bg-yellow-900/30 border-b border-yellow-200 dark:border-yellow-800">
          <p className="text-yellow-700 dark:text-yellow-400 text-sm">{voiceError}</p>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message, index) => (
          <div key={message.id || index} className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] rounded-lg p-3 ${
              message.sender === 'user'
                ? 'bg-blue-500 text-white ml-auto'
                : 'bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-white mr-auto'
            }`}>
              <div className="flex items-center mb-1">
                {message.sender === 'agent' && (
                  <img src="/logo-neon.png" alt="Archon" className="w-4 h-4 mr-1" />
                )}
                <span className="text-xs opacity-70">
                  {formatTime(message.timestamp)}
                </span>
                {/* Show recognized language for recent voice user messages */}
                {message.sender === 'user' && (() => {
                  const ts = typeof message.timestamp === 'string' ? new Date(message.timestamp).getTime() : (message.timestamp as Date).getTime();
                  const match = recentVoiceSendsRef.current.find(entry => entry.content === message.content && Math.abs(ts - entry.ts) < 30000);
                  return match ? (
                    <span className="ml-2 text-[10px] px-1.5 py-0.5 rounded bg-blue-600/20 text-blue-200 border border-blue-500/40" title="Speech input language">
                      ASR: {match.lang}
                    </span>
                  ) : null;
                })()}
              </div>
              <p className="text-sm whitespace-pre-wrap">{message.content}</p>
            </div>
          </div>
        ))}

        {/* Typing indicator */}
        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-gray-100 dark:bg-gray-800 rounded-lg p-3 mr-auto">
              <ArchonLoadingSpinner />
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input area */}
      <div className="p-4 border-t border-gray-200 dark:border-gray-700 bg-white/80 dark:bg-black/40">
        <div className="flex items-center gap-2">
          {/* Voice button */}
          {isVoiceEnabled && (
            <Tooltip.Provider delayDuration={200}>
              <Tooltip.Root>
                <Tooltip.Trigger asChild>
                  <button
                    onClick={() => {
                      console.log('Voice button clicked. Currently listening:', isListening);
                      if (isListening) {
                        console.log('Stopping voice recognition...');
                        stopListening();
                      } else {
                        console.log('Starting voice recognition...');
                        startListening();
                      }
                    }}
                    disabled={connectionStatus !== 'online'}
                    className={`p-2 rounded-full transition-all duration-200 ${
                      isListening
                        ? 'bg-red-500 text-white animate-pulse'
                        : 'bg-blue-500 text-white hover:bg-blue-600'
                    } disabled:opacity-50 disabled:cursor-not-allowed`}
                  >
                    {isListening ? <MicOff className="w-4 h-4" /> : <Mic className="w-4 h-4" />}
                  </button>
                </Tooltip.Trigger>
                <Tooltip.Content side="top" align="center" sideOffset={6} className="rounded bg-gray-900 text-white px-2 py-1 text-xs shadow">
                  {(() => {
                    const preferred = getRecognitionLang();
                    const modeLabel = recognitionMode === 'auto' ? `Auto → ${preferred}` : preferred;
                    return `Mic: ${modeLabel}${isListening ? ' (listening)' : ''}`;
                  })()}
                  <Tooltip.Arrow className="fill-gray-900" />
                </Tooltip.Content>
              </Tooltip.Root>
            </Tooltip.Provider>
          )}

          {/* Text input */}
          <div className="flex-1 relative flex items-center gap-2">
            <input
              type="text"
              value={inputValue}
              onChange={e => setInputValue(e.target.value)}
                placeholder={
                  connectionStatus === 'offline' ? 'Chat is offline...' :
                  connectionStatus === 'connecting' ? 'Connecting...' :
                  isVoiceEnabled ? `Speak or type to ${selectedAgent?.label || 'Agent'}...` :
                  `Message ${selectedAgent?.label || 'Agent'}...`
                }
              disabled={connectionStatus !== 'online'}
              className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
              onKeyDown={e => {
                if (e.key === 'Enter') handleSendMessage();
              }}
            />
          </div>

          {/* Send button */}
          <button
            onClick={() => handleSendMessage()}
            disabled={connectionStatus !== 'online' || isTyping || !inputValue.trim()}
            className="p-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            title="Send message"
          >
            <Send className="w-4 h-4" />
          </button>
        </div>

        {/* Voice status */}
        {isVoiceEnabled && (
          <div className="mt-2 flex items-center justify-between text-xs text-gray-500 dark:text-gray-400">
            <span>
              {isListening ? 'Escuchando...' : isSpeaking ? 'Hablando...' : 'Presiona el micrófono para hablar'}
            </span>
            {voiceSupported && (
              <span className="text-green-600 dark:text-green-400">Voice ready</span>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Bug, X, Send, Copy, Loader } from "lucide-react";
import { Button } from "../ui/Button";
import { Input } from "../ui/Input";
import { Card } from "../ui/Card";
import { Select } from "../ui/Select";
import { useToast } from "../../contexts/ToastContext";
import {
  bugReportService,
  BugContext,
  BugReportData,
} from "../../services/bugReportService";

interface BugReportModalProps {
  isOpen: boolean;
  onClose: () => void;
  context: BugContext;
}

export const BugReportModal: React.FC<BugReportModalProps> = ({
  isOpen,
  onClose,
  context,
}) => {
  const [report, setReport] = useState<Omit<BugReportData, "context">>({
    title: `🐛 ${context.error.name}: ${context.error.message}`,
    description: "",
    stepsToReproduce: "",
    expectedBehavior: "",
    actualBehavior: context.error.message,
    severity: "medium",
    component: "not-sure",
  });

  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const { showToast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!report.description.trim()) {
      showToast(
        "Please provide a description of what you were trying to do",
        "error",
      );
      return;
    }

    setSubmitting(true);

    try {
      const bugReportData: BugReportData = {
        ...report,
        context,
      };

      const result = await bugReportService.submitBugReport(bugReportData);

      if (result.success) {
        setSubmitted(true);

        if (result.issueNumber) {
          // Direct API creation (maintainer with token)
          showToast(
            `Bug report created! Issue #${result.issueNumber} - maintainers will review it soon.`,
            "success",
            8000,
          );
          if (result.issueUrl) {
            window.open(result.issueUrl, "_blank");
          }
        } else {
          // Manual submission (open source user - no token)
          showToast(
            "Opening GitHub to submit your bug report...",
            "success",
            5000,
          );
          if (result.issueUrl) {
            // Force new tab/window opening
            const newWindow = window.open(
              result.issueUrl,
              "_blank",
              "noopener,noreferrer",
            );
            if (!newWindow) {
              // Popup blocked - show manual link
              showToast(
                "Popup blocked! Please allow popups or click the link in the modal.",
                "warning",
                8000,
              );
            }
          }
        }
      } else {
        // Fallback: copy to clipboard
        const formattedReport =
          bugReportService.formatReportForClipboard(bugReportData);
        await navigator.clipboard.writeText(formattedReport);

        showToast(
          "Failed to create GitHub issue, but bug report was copied to clipboard. Please paste it in a new GitHub issue.",
          "warning",
          10000,
        );
      }
    } catch (error) {
      console.error("Bug report submission failed:", error);
      showToast(
        "Failed to submit bug report. Please try again or report manually.",
        "error",
      );
    } finally {
      setSubmitting(false);
    }
  };

  const copyToClipboard = async () => {
    const bugReportData: BugReportData = { ...report, context };
    const formattedReport =
      bugReportService.formatReportForClipboard(bugReportData);

    try {
      await navigator.clipboard.writeText(formattedReport);
      showToast("Bug report copied to clipboard", "success");
    } catch {
      showToast("Failed to copy to clipboard", "error");
    }
  };

  if (!isOpen) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        exit={{ opacity: 0 }}
        className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4"
        onClick={onClose}
      >
        <motion.div
          initial={{ scale: 0.95, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          exit={{ scale: 0.95, opacity: 0 }}
          className="w-full max-w-2xl max-h-[90vh] overflow-y-auto"
          onClick={(e) => e.stopPropagation()}
        >
          <Card className="relative">
            {/* Header */}
            <div className="flex items-center justify-between p-6 border-b border-gray-200 dark:border-gray-700">
              <div className="flex items-center gap-3">
                <Bug className="w-6 h-6 text-red-500" />
                <h2 className="text-xl font-bold text-gray-800 dark:text-white">
                  Report Bug
                </h2>
              </div>
              <button
                onClick={onClose}
                className="p-2 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
            </div>

            {submitted ? (
              /* Success State */
              <div className="p-6 text-center">
                <div className="w-16 h-16 mx-auto mb-4 bg-green-100 dark:bg-green-900/20 rounded-full flex items-center justify-center">
                  <Bug className="w-8 h-8 text-green-600 dark:text-green-400" />
                </div>
                <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-2">
                  Bug Report Submitted!
                </h3>
                <p className="text-gray-600 dark:text-gray-400 mb-4">
                  Thank you for helping improve Archon. Maintainers will review
                  your report and may comment @claude to trigger automatic
                  analysis and fixes.
                </p>
                <Button onClick={onClose}>Close</Button>
              </div>
            ) : (
              /* Form */
              <form onSubmit={handleSubmit} className="p-6 space-y-6">
                {/* Error Preview */}
                <div className="bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 rounded-md p-3">
                  <div className="font-medium text-red-800 dark:text-red-200 text-sm">
                    {context.error.name}: {context.error.message}
                  </div>
                  {context.error.stack && (
                    <details className="mt-2">
                      <summary className="text-red-600 dark:text-red-400 text-xs cursor-pointer">
                        Stack trace
                      </summary>
                      <pre className="text-xs text-red-600 dark:text-red-400 mt-1 overflow-auto max-h-32">
                        {context.error.stack}
                      </pre>
                    </details>
                  )}
                </div>

                {/* Bug Title */}
                <Input
                  label="Bug Title"
                  value={report.title}
                  onChange={(e) =>
                    setReport((r) => ({ ...r, title: e.target.value }))
                  }
                  placeholder="Brief description of the bug"
                  required
                />

                {/* Severity & Component */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <Select
                    label="Severity"
                    value={report.severity}
                    onChange={(e) =>
                      setReport((r) => ({
                        ...r,
                        severity: e.target.value as any,
                      }))
                    }
                    options={[
                      { value: "low", label: "🟢 Low - Minor inconvenience" },
                      {
                        value: "medium",
                        label: "🟡 Medium - Affects functionality",
                      },
                      {
                        value: "high",
                        label: "🟠 High - Blocks important features",
                      },
                      {
                        value: "critical",
                        label: "🔴 Critical - App unusable",
                      },
                    ]}
                  />

                  <Select
                    label="Component"
                    value={report.component}
                    onChange={(e) =>
                      setReport((r) => ({ ...r, component: e.target.value }))
                    }
                    options={[
                      {
                        value: "knowledge-base",
                        label: "🔍 Knowledge Base / RAG",
                      },
                      { value: "mcp-integration", label: "🔗 MCP Integration" },
                      { value: "projects-tasks", label: "📋 Projects & Tasks" },
                      {
                        value: "settings",
                        label: "⚙️ Settings & Configuration",
                      },
                      { value: "ui", label: "🖥️ User Interface" },
                      {
                        value: "infrastructure",
                        label: "🐳 Docker / Infrastructure",
                      },
                      { value: "not-sure", label: "❓ Not Sure" },
                    ]}
                  />
                </div>

                {/* Description */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    What were you trying to do? *
                  </label>
                  <textarea
                    value={report.description}
                    onChange={(e) =>
                      setReport((r) => ({ ...r, description: e.target.value }))
                    }
                    placeholder="I was trying to crawl a documentation site when..."
                    className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    rows={3}
                    required
                  />
                </div>

                {/* Steps to Reproduce */}
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                    Steps to Reproduce
                  </label>
                  <textarea
                    value={report.stepsToReproduce}
                    onChange={(e) =>
                      setReport((r) => ({
                        ...r,
                        stepsToReproduce: e.target.value,
                      }))
                    }
                    placeholder="1. Go to Knowledge Base page&#10;2. Click Add Knowledge&#10;3. Enter URL...&#10;4. Error occurs"
                    className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                    rows={4}
                  />
                </div>

                {/* Expected vs Actual Behavior */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      Expected Behavior
                    </label>
                    <textarea
                      value={report.expectedBehavior}
                      onChange={(e) =>
                        setReport((r) => ({
                          ...r,
                          expectedBehavior: e.target.value,
                        }))
                      }
                      placeholder="What should have happened?"
                      className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      rows={3}
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                      Actual Behavior
                    </label>
                    <textarea
                      value={report.actualBehavior}
                      onChange={(e) =>
                        setReport((r) => ({
                          ...r,
                          actualBehavior: e.target.value,
                        }))
                      }
                      placeholder="What actually happened?"
                      className="w-full p-3 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                      rows={3}
                    />
                  </div>
                </div>

                {/* System Info Preview */}
                <details className="text-sm">
                  <summary className="cursor-pointer text-gray-600 dark:text-gray-400 hover:text-gray-800 dark:hover:text-gray-200">
                    System information that will be included
                  </summary>
                  <div className="mt-2 p-3 bg-gray-50 dark:bg-gray-800 rounded text-xs">
                    <div>
                      <strong>Version:</strong> {context.app.version}
                    </div>
                    <div>
                      <strong>Platform:</strong> {context.system.platform}
                    </div>
                    <div>
                      <strong>Memory:</strong> {context.system.memory}
                    </div>
                    <div>
                      <strong>Services:</strong> Server{" "}
                      {context.services.server ? "✅" : "❌"}, MCP{" "}
                      {context.services.mcp ? "✅" : "❌"}, Agents{" "}
                      {context.services.agents ? "✅" : "❌"}
                    </div>
                  </div>
                </details>

                {/* Actions */}
                <div className="flex flex-col sm:flex-row gap-3 justify-end pt-4 border-t border-gray-200 dark:border-gray-700">
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={copyToClipboard}
                    className="sm:order-1"
                  >
                    <Copy className="w-4 h-4 mr-2" />
                    Copy to Clipboard
                  </Button>

                  <Button
                    type="button"
                    variant="ghost"
                    onClick={onClose}
                    disabled={submitting}
                    className="sm:order-2"
                  >
                    Cancel
                  </Button>

                  <Button
                    type="submit"
                    disabled={submitting || !report.description.trim()}
                    className="sm:order-3"
                  >
                    {submitting ? (
                      <>
                        <Loader className="w-4 h-4 mr-2 animate-spin" />
                        Creating Issue...
                      </>
                    ) : (
                      <>
                        <Send className="w-4 h-4 mr-2" />
                        Submit Bug Report
                      </>
                    )}
                  </Button>
                </div>
              </form>
            )}
          </Card>
        </motion.div>
      </motion.div>
    </AnimatePresence>
  );
};

import React, { Component, ErrorInfo, ReactNode } from "react";
import { AlertCircle, Bug, RefreshCw } from "lucide-react";
import { Button } from "../ui/Button";
import { Card } from "../ui/Card";
import { BugReportModal } from "./BugReportModal";
import { bugReportService, BugContext } from "../../services/bugReportService";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, errorInfo: ErrorInfo) => ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  showBugReport: boolean;
  bugContext: BugContext | null;
}

export class ErrorBoundaryWithBugReport extends Component<Props, State> {
  constructor(props: Props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      showBugReport: false,
      bugContext: null,
    };
  }

  static getDerivedStateFromError(error: Error): Partial<State> {
    return {
      hasError: true,
      error,
    };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("ErrorBoundary caught an error:", error, errorInfo);

    this.setState({
      error,
      errorInfo,
    });

    // Collect bug context automatically when error occurs
    this.collectBugContext(error);
  }

  private async collectBugContext(error: Error) {
    try {
      const context = await bugReportService.collectBugContext(error);
      this.setState({ bugContext: context });
    } catch (contextError) {
      console.error("Failed to collect bug context:", contextError);
    }
  }

  private handleReportBug = () => {
    this.setState({ showBugReport: true });
  };

  private handleCloseBugReport = () => {
    this.setState({ showBugReport: false });
  };

  private handleRetry = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      showBugReport: false,
      bugContext: null,
    });
  };

  private handleReload = () => {
    window.location.reload();
  };

  render() {
    if (this.state.hasError && this.state.error) {
      // Custom fallback if provided
      if (this.props.fallback) {
        return this.props.fallback(this.state.error, this.state.errorInfo!);
      }

      // Default error UI
      return (
        <>
          <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center p-4">
            <Card className="max-w-lg w-full">
              <div className="p-6 text-center">
                {/* Error Icon */}
                <div className="w-16 h-16 mx-auto mb-4 bg-red-100 dark:bg-red-900/20 rounded-full flex items-center justify-center">
                  <AlertCircle className="w-8 h-8 text-red-600 dark:text-red-400" />
                </div>

                {/* Error Title */}
                <h1 className="text-xl font-bold text-gray-800 dark:text-white mb-2">
                  Something went wrong
                </h1>

                {/* Error Message */}
                <p className="text-gray-600 dark:text-gray-400 mb-4">
                  {this.state.error.message}
                </p>

                {/* Error Details (collapsible) */}
                <details className="text-left mb-6">
                  <summary className="cursor-pointer text-gray-500 hover:text-gray-700 dark:hover:text-gray-300 text-sm">
                    Technical details
                  </summary>
                  <div className="mt-2 p-3 bg-gray-100 dark:bg-gray-800 rounded text-xs font-mono overflow-auto max-h-32">
                    <div className="mb-2">
                      <strong>Error:</strong> {this.state.error.name}
                    </div>
                    <div className="mb-2">
                      <strong>Message:</strong> {this.state.error.message}
                    </div>
                    {this.state.error.stack && (
                      <div>
                        <strong>Stack:</strong>
                        <pre className="mt-1 whitespace-pre-wrap">
                          {this.state.error.stack}
                        </pre>
                      </div>
                    )}
                  </div>
                </details>

                {/* Action Buttons */}
                <div className="flex flex-col sm:flex-row gap-3 justify-center">
                  <Button onClick={this.handleRetry} variant="ghost">
                    <RefreshCw className="w-4 h-4 mr-2" />
                    Try Again
                  </Button>

                  <Button onClick={this.handleReload} variant="ghost">
                    Reload Page
                  </Button>

                  <Button
                    onClick={this.handleReportBug}
                    className="bg-red-600 hover:bg-red-700 text-white"
                    disabled={!this.state.bugContext}
                  >
                    <Bug className="w-4 h-4 mr-2" />
                    Report Bug
                  </Button>
                </div>

                {/* Help Text */}
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-6">
                  If this keeps happening, please report the bug so we can fix
                  it.
                </p>
              </div>
            </Card>
          </div>

          {/* Bug Report Modal */}
          {this.state.bugContext && (
            <BugReportModal
              isOpen={this.state.showBugReport}
              onClose={this.handleCloseBugReport}
              context={this.state.bugContext}
            />
          )}
        </>
      );
    }

    return this.props.children;
  }
}

import { useState } from 'react';
import { 
  LinkIcon, 
  Upload, 
  BoxIcon, 
  Brain
} from 'lucide-react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { Badge } from '../ui/Badge';
import { GlassCrawlDepthSelector } from '../ui/GlassCrawlDepthSelector';
import { useToast } from '../../contexts/ToastContext';
import { knowledgeBaseService } from '../../services/knowledgeBaseService';
import { CrawlProgressData } from '../../types/crawl';

interface AddKnowledgeModalProps {
  onClose: () => void;
  onSuccess: () => void;
  onStartCrawl: (progressId: string, initialData: Partial<CrawlProgressData>) => void;
}

export const AddKnowledgeModal = ({
  onClose,
  onSuccess,
  onStartCrawl
}: AddKnowledgeModalProps) => {
  const [method, setMethod] = useState<'url' | 'file'>('url');
  const [url, setUrl] = useState('');
  const [tags, setTags] = useState<string[]>([]);
  const [newTag, setNewTag] = useState('');
  const [knowledgeType, setKnowledgeType] = useState<'technical' | 'business'>('technical');
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [crawlDepth, setCrawlDepth] = useState(2);
  const [showDepthTooltip, setShowDepthTooltip] = useState(false);
  const { showToast } = useToast();

  // URL validation function
  const validateUrl = async (url: string): Promise<{ isValid: boolean; error?: string; formattedUrl?: string }> => {
    try {
      let formattedUrl = url.trim();
      if (!formattedUrl.startsWith('http://') && !formattedUrl.startsWith('https://')) {
        formattedUrl = `https://${formattedUrl}`;
      }

      let urlObj;
      try {
        urlObj = new URL(formattedUrl);
      } catch {
        return { isValid: false, error: 'Please enter a valid URL format' };
      }

      const hostname = urlObj.hostname;
      if (!hostname || hostname === 'localhost' || /^\d+\.\d+\.\d+\.\d+$/.test(hostname)) {
        return { isValid: true, formattedUrl };
      }

      if (!hostname.includes('.')) {
        return { isValid: false, error: 'Please enter a valid domain name' };
      }

      const parts = hostname.split('.');
      const tld = parts[parts.length - 1];
      if (tld.length < 2) {
        return { isValid: false, error: 'Please enter a valid domain with a proper extension' };
      }

      // Optional DNS check
      try {
        const response = await fetch(`https://dns.google/resolve?name=${hostname}&type=A`, {
          method: 'GET',
          headers: { 'Accept': 'application/json' }
        });

        if (response.ok) {
          const dnsResult = await response.json();
          if (dnsResult.Status === 0 && dnsResult.Answer?.length > 0) {
            return { isValid: true, formattedUrl };
          } else {
            return { isValid: false, error: `Domain "${hostname}" could not be resolved` };
          }
        }
      } catch {
        // Allow URL even if DNS check fails
        console.warn('DNS check failed, allowing URL anyway');
      }

      return { isValid: true, formattedUrl };
    } catch {
      return { isValid: false, error: 'URL validation failed' };
    }
  };

  const handleSubmit = async () => {
    try {
      setLoading(true);

      if (method === 'url') {
        if (!url.trim()) {
          showToast('Please enter a URL', 'error');
          return;
        }

        showToast('Validating URL...', 'info');
        const validation = await validateUrl(url);

        if (!validation.isValid) {
          showToast(validation.error || 'Invalid URL', 'error');
          return;
        }

        const formattedUrl = validation.formattedUrl!;
        setUrl(formattedUrl);

        // Detect crawl type based on URL
        const crawlType = detectCrawlType(formattedUrl);

        const result = await knowledgeBaseService.crawlUrl({
          url: formattedUrl,
          knowledge_type: knowledgeType,
          tags,
          max_depth: crawlDepth
        });

        if ((result as any).progressId) {
          onStartCrawl((result as any).progressId, {
            status: 'initializing',
            progress: 0,
            currentStep: 'Starting crawl',
            crawlType,
            currentUrl: formattedUrl,
            originalCrawlParams: {
              url: formattedUrl,
              knowledge_type: knowledgeType,
              tags,
              max_depth: crawlDepth
            }
          });

          showToast(`Starting ${crawlType} crawl...`, 'success');
          onClose();
        } else {
          showToast((result as any).message || 'Crawling started', 'success');
          onSuccess();
        }
      } else {
        if (!selectedFile) {
          showToast('Please select a file', 'error');
          return;
        }

        const result = await knowledgeBaseService.uploadDocument(selectedFile, {
          knowledge_type: knowledgeType,
          tags
        });

        if (result.success && result.progressId) {
          onStartCrawl(result.progressId, {
            currentUrl: `file://${selectedFile.name}`,
            progress: 0,
            status: 'starting',
            uploadType: 'document',
            fileName: selectedFile.name,
            fileType: selectedFile.type,
            originalUploadParams: {
              file: selectedFile,
              knowledge_type: knowledgeType,
              tags
            }
          });

          showToast('Document upload started', 'success');
          onClose();
        } else {
          showToast(result.message || 'Document uploaded', 'success');
          onSuccess();
        }
      }
    } catch (error) {
      console.error('Failed to add knowledge:', error);
      showToast('Failed to add knowledge source', 'error');
    } finally {
      setLoading(false);
    }
  };

  // Helper to detect crawl type
  const detectCrawlType = (url: string): 'sitemap' | 'llms-txt' | 'normal' => {
    if (url.includes('sitemap.xml')) return 'sitemap';
    if (url.includes('llms') && url.endsWith('.txt')) return 'llms-txt';
    return 'normal';
  };

  return (
    <div className="fixed inset-0 bg-gray-500/50 dark:bg-black/80 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <Card className="w-full max-w-2xl relative before:content-[''] before:absolute before:top-0 before:left-0 before:w-full before:h-[1px] before:bg-green-500 p-8">
        <h2 className="text-xl font-bold text-gray-800 dark:text-white mb-8">
          Add Knowledge Source
        </h2>

        {/* Knowledge Type Selection */}
        <div className="mb-6">
          <label className="block text-gray-600 dark:text-zinc-400 text-sm mb-2">
            Knowledge Type
          </label>
          <div className="flex gap-4">
            <label className={`
              flex-1 p-4 rounded-md border cursor-pointer transition flex items-center justify-center gap-2
              ${knowledgeType === 'technical' 
                ? 'border-blue-500 text-blue-600 dark:text-blue-500 bg-blue-50 dark:bg-blue-500/5' 
                : 'border-gray-200 dark:border-zinc-900 text-gray-500 dark:text-zinc-400 hover:border-blue-300 dark:hover:border-blue-500/30'}
            `}>
              <input 
                type="radio" 
                name="knowledgeType" 
                value="technical" 
                checked={knowledgeType === 'technical'} 
                onChange={() => setKnowledgeType('technical')} 
                className="sr-only" 
              />
              <BoxIcon className="w-5 h-5" />
              <span>Technical/Coding</span>
            </label>
            <label className={`
              flex-1 p-4 rounded-md border cursor-pointer transition flex items-center justify-center gap-2
              ${knowledgeType === 'business' 
                ? 'border-purple-500 text-purple-600 dark:text-purple-500 bg-purple-50 dark:bg-purple-500/5' 
                : 'border-gray-200 dark:border-zinc-900 text-gray-500 dark:text-zinc-400 hover:border-purple-300 dark:hover:border-purple-500/30'}
            `}>
              <input 
                type="radio" 
                name="knowledgeType" 
                value="business" 
                checked={knowledgeType === 'business'} 
                onChange={() => setKnowledgeType('business')} 
                className="sr-only" 
              />
              <Brain className="w-5 h-5" />
              <span>Business/Project</span>
            </label>
          </div>
        </div>

        {/* Source Type Selection */}
        <div className="flex gap-4 mb-6">
          <button 
            onClick={() => setMethod('url')} 
            className={`flex-1 p-4 rounded-md border transition flex items-center justify-center gap-2
              ${method === 'url' 
                ? 'border-blue-500 text-blue-600 dark:text-blue-500 bg-blue-50 dark:bg-blue-500/5' 
                : 'border-gray-200 dark:border-zinc-900 text-gray-500 dark:text-zinc-400 hover:border-blue-300 dark:hover:border-blue-500/30'}`}
          >
            <LinkIcon className="w-4 h-4" />
            <span>URL / Website</span>
          </button>
          <button 
            onClick={() => setMethod('file')} 
            className={`flex-1 p-4 rounded-md border transition flex items-center justify-center gap-2
              ${method === 'file' 
                ? 'border-pink-500 text-pink-600 dark:text-pink-500 bg-pink-50 dark:bg-pink-500/5' 
                : 'border-gray-200 dark:border-zinc-900 text-gray-500 dark:text-zinc-400 hover:border-pink-300 dark:hover:border-pink-500/30'}`}
          >
            <Upload className="w-4 h-4" />
            <span>Upload File</span>
          </button>
        </div>

        {/* URL Input */}
        {method === 'url' && (
          <div className="mb-6">
            <Input 
              label="URL to Scrape" 
              type="url" 
              value={url} 
              onChange={(e) => setUrl(e.target.value)} 
              placeholder="https://example.com or example.com" 
              accentColor="blue" 
            />
            {url && !url.startsWith('http://') && !url.startsWith('https://') && (
              <p className="text-amber-600 dark:text-amber-400 text-sm mt-1">
                ℹ️ Will automatically add https:// prefix
              </p>
            )}
          </div>
        )}

        {/* File Upload */}
        {method === 'file' && (
          <div className="mb-6">
            <label className="block text-gray-600 dark:text-zinc-400 text-sm mb-2">
              Upload Document
            </label>
            <div className="relative">
              <input 
                id="file-upload"
                type="file"
                accept=".pdf,.md,.doc,.docx,.txt"
                onChange={(e) => setSelectedFile(e.target.files?.[0] || null)}
                className="sr-only"
              />
              <label 
                htmlFor="file-upload"
                className="flex items-center justify-center gap-3 w-full p-6 rounded-md border-2 border-dashed cursor-pointer transition-all duration-300
                  bg-blue-500/10 hover:bg-blue-500/20 
                  border-blue-500/30 hover:border-blue-500/50
                  text-blue-600 dark:text-blue-400
                  hover:shadow-[0_0_15px_rgba(59,130,246,0.3)]
                  backdrop-blur-sm"
              >
                <Upload className="w-6 h-6" />
                <div className="text-center">
                  <div className="font-medium">
                    {selectedFile ? selectedFile.name : 'Choose File'}
                  </div>
                  <div className="text-sm opacity-75 mt-1">
                    {selectedFile 
                      ? `${(selectedFile.size / 1024 / 1024).toFixed(2)} MB` 
                      : 'Click to browse or drag and drop'}
                  </div>
                </div>
              </label>
            </div>
            <p className="text-gray-500 dark:text-zinc-600 text-sm mt-2">
              Supports PDF, MD, DOC up to 10MB
            </p>
          </div>
        )}

        {/* Crawl Depth - Only for URLs */}
        {method === 'url' && (
          <div className="mb-6">
            <label className="block text-gray-600 dark:text-zinc-400 text-sm mb-4">
              Crawl Depth
              <button
                type="button"
                className="ml-2 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
                onMouseEnter={() => setShowDepthTooltip(true)}
                onMouseLeave={() => setShowDepthTooltip(false)}
              >
                <svg className="w-4 h-4 inline" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </button>
            </label>

            <GlassCrawlDepthSelector
              value={crawlDepth}
              onChange={setCrawlDepth}
              showTooltip={showDepthTooltip}
              onTooltipToggle={setShowDepthTooltip}
            />
          </div>
        )}

        {/* Tags */}
        <div className="mb-6">
          <label className="block text-gray-600 dark:text-zinc-400 text-sm mb-2">
            Tags (AI will add recommended tags if left blank)
          </label>
          <div className="flex flex-wrap gap-2 mb-2">
            {tags.map((tag) => (
              <Badge key={tag} color="purple" variant="outline">
                {tag}
                <button
                  onClick={() => setTags(tags.filter(t => t !== tag))}
                  className="ml-1 text-purple-600 hover:text-purple-800"
                >
                  ×
                </button>
              </Badge>
            ))}
          </div>
          <Input 
            type="text" 
            value={newTag} 
            onChange={(e) => setNewTag(e.target.value)} 
            onKeyDown={(e) => {
              if (e.key === 'Enter' && newTag.trim()) {
                setTags([...tags, newTag.trim()]);
                setNewTag('');
              }
            }} 
            placeholder="Add tags..." 
            accentColor="purple" 
          />
        </div>

        {/* Action Buttons */}
        <div className="flex justify-end gap-4">
          <Button onClick={onClose} variant="ghost" disabled={loading}>
            Cancel
          </Button>
          <Button 
            onClick={handleSubmit} 
            variant="primary" 
            accentColor={method === 'url' ? 'blue' : 'pink'} 
            disabled={loading}
          >
            {loading ? 'Adding...' : 'Add Source'}
          </Button>
        </div>
      </Card>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { 
  Activity,
  AlertTriangle,
  CheckCircle,
  ChevronDown,
  ChevronUp,

  Globe,
  FileText,
  RotateCcw,
  X,
  FileCode,
  Upload,
  Search,
  Cpu,
  Database,
  Code,
  Zap,
  Square,
  Layers,
  Download
} from 'lucide-react';
import { Card } from '../ui/Card';
import { Button } from '../ui/Button';
import { Badge } from '../ui/Badge';
import { CrawlProgressData } from '../../types/crawl';
import { useCrawlProgressPolling } from '../../hooks/useCrawlQueries';
import { useTerminalScroll } from '../../hooks/useTerminalScroll';

interface CrawlingProgressCardProps {
  progressId: string;
  initialData?: Partial<CrawlProgressData>;
  onComplete?: (data: CrawlProgressData) => void;
  onError?: (error: string) => void;
  onRetry?: () => void;
  onDismiss?: () => void;
  onStop?: () => void;
}

// Simple mapping of backend status to UI display
const STATUS_CONFIG = {
  // Common statuses
  'starting': { label: 'Starting', icon: <Activity className="w-4 h-4" />, color: 'blue' },
  'initializing': { label: 'Initializing', icon: <Activity className="w-4 h-4" />, color: 'blue' },

  // Crawl statuses
  'analyzing': { label: 'Analyzing URL', icon: <Search className="w-4 h-4" />, color: 'purple' },
  'crawling': { label: 'Crawling Pages', icon: <Globe className="w-4 h-4" />, color: 'blue' },
  'processing': { label: 'Processing Content', icon: <Cpu className="w-4 h-4" />, color: 'cyan' },
  'source_creation': { label: 'Creating Source', icon: <FileText className="w-4 h-4" />, color: 'indigo' },
  'document_storage': { label: 'Storing Documents', icon: <Database className="w-4 h-4" />, color: 'green' },
  'code_extraction': { label: 'Extracting Code', icon: <Code className="w-4 h-4" />, color: 'yellow' },
  'finalization': { label: 'Finalizing', icon: <Zap className="w-4 h-4" />, color: 'orange' },

  // Upload statuses
  'reading': { label: 'Reading File', icon: <Download className="w-4 h-4" />, color: 'blue' },
  'extracting': { label: 'Extracting Text', icon: <FileText className="w-4 h-4" />, color: 'blue' },
  'chunking': { label: 'Chunking Content', icon: <Cpu className="w-4 h-4" />, color: 'blue' },
  'creating_source': { label: 'Creating Source', icon: <Database className="w-4 h-4" />, color: 'blue' },
  'summarizing': { label: 'Generating Summary', icon: <Search className="w-4 h-4" />, color: 'purple' },
  'storing': { label: 'Storing Chunks', icon: <Database className="w-4 h-4" />, color: 'green' },

  // End states
  'completed': { label: 'Completed', icon: <CheckCircle className="w-4 h-4" />, color: 'green' },
  'error': { label: 'Error', icon: <AlertTriangle className="w-4 h-4" />, color: 'red' },
  'failed': { label: 'Failed', icon: <AlertTriangle className="w-4 h-4" />, color: 'red' },
  'cancelled': { label: 'Cancelled', icon: <X className="w-4 h-4" />, color: 'gray' },
  'stopping': { label: 'Stopping', icon: <Square className="w-4 h-4" />, color: 'orange' },
} as const;

export const CrawlingProgressCard: React.FC<CrawlingProgressCardProps> = ({
  progressId,
  initialData,
  onComplete,
  onError,
  onRetry,
  onDismiss,
  onStop
}) => {
  const [showDetailedProgress, setShowDetailedProgress] = useState(true);
  const [showLogs, setShowLogs] = useState(false);
  const [isStopping, setIsStopping] = useState(false);

  // Track completion/error handling
  const [hasHandledCompletion, setHasHandledCompletion] = useState(false);
  const [hasHandledError, setHasHandledError] = useState(false);

  // Poll for progress updates
  const { data: progressData } = useCrawlProgressPolling(progressId, {
    onError: (error: Error) => {
      if (error.message === 'Resource no longer exists') {
        if (onDismiss) {
          onDismiss();
        }
      }
    }
  });

  // Merge polled data with initial data - preserve important fields
  const displayData = progressData ? {
    ...initialData,
    ...progressData,
    // Ensure we don't lose these fields during polling
    currentUrl: progressData.currentUrl || progressData.current_url || initialData?.currentUrl,
    crawlType: progressData.crawlType || progressData.crawl_type || initialData?.crawlType,
  } : {
    progressId,
    status: 'starting',
    progress: 0,
    message: 'Initializing...',
    ...initialData
  } as CrawlProgressData;

  // Use terminal scroll hook for logs
  const logsContainerRef = useTerminalScroll(
    displayData?.logs || [], 
    showLogs
  );

  // Handle status changes
  useEffect(() => {
    if (!progressData) return;

    if (progressData.status === 'completed' && !hasHandledCompletion && onComplete) {
      setHasHandledCompletion(true);
      onComplete(progressData);
    } else if ((progressData.status === 'error' || progressData.status === 'failed') && !hasHandledError && onError) {
      setHasHandledError(true);
      onError(progressData.error || 'Unknown error');
    }
  }, [progressData?.status, hasHandledCompletion, hasHandledError, onComplete, onError]);

  // Get current status config with better fallback
  const statusConfig = (() => {
    const config = STATUS_CONFIG[displayData.status as keyof typeof STATUS_CONFIG];
    if (config) {
      return config;
    }

    // Better fallbacks based on progress
    if (displayData.progress >= 100) {
      return STATUS_CONFIG.completed;
    }
    if (displayData.progress > 90) {
      return STATUS_CONFIG.finalization;
    }

    // Log unknown statuses for debugging
    console.warn(`Unknown status: ${displayData.status}, progress: ${displayData.progress}%, message: ${displayData.message}`);

    return STATUS_CONFIG.processing;
  })();

  // Debug log for status transitions
  useEffect(() => {
    if (displayData.status === 'finalization' || 
        (displayData.status === 'starting' && displayData.progress > 90)) {
      console.log('Status transition debug:', {
        status: displayData.status,
        progress: displayData.progress,
        message: displayData.message,
        hasStatusConfig: !!STATUS_CONFIG[displayData.status as keyof typeof STATUS_CONFIG]
      });
    }
  }, [displayData.status, displayData.progress]);

  // Determine crawl type display
  const getCrawlTypeDisplay = () => {
    const crawlType = displayData.crawlType || 
      (displayData.uploadType === 'document' ? 'upload' : 'normal');

    switch (crawlType) {
      case 'sitemap':
        return { icon: <Layers className="w-4 h-4" />, label: 'Sitemap Crawl' };
      case 'llms-txt':
      case 'text_file':
        return { icon: <FileCode className="w-4 h-4" />, label: 'LLMs.txt Import' };
      case 'upload':
        return { icon: <Upload className="w-4 h-4" />, label: 'Document Upload' };
      default:
        return { icon: <Globe className="w-4 h-4" />, label: 'Web Crawl' };
    }
  };

  const crawlType = getCrawlTypeDisplay();
  // Safe batch metrics
  const safeTotalBatches = ((displayData as any).totalBatches ?? (displayData as any).total_batches ?? 0) as number;
  const safeCompletedBatches = ((displayData as any).completedBatches ?? (displayData as any).completed_batches ?? 0) as number;

  // Handle stop
  const handleStop = async () => {
    if (isStopping || !onStop) return;
    setIsStopping(true);
    try {
      onStop();
    } finally {
      setIsStopping(false);
    }
  };

  // Get progress steps based on type
  const getProgressSteps = () => {
    const isUpload = displayData.uploadType === 'document';

    const steps = isUpload ? [
      'reading', 'extracting', 'chunking', 'creating_source', 'summarizing', 'storing'
    ] : [
      'analyzing', 'crawling', 'processing', 'source_creation', 'document_storage', 'code_extraction', 'finalization'
    ];

    return steps.map(stepId => {
      const config = STATUS_CONFIG[stepId as keyof typeof STATUS_CONFIG];
      const currentIndex = steps.indexOf(displayData.status || '');
      const stepIndex = steps.indexOf(stepId);

      let status: 'pending' | 'active' | 'completed' | 'error' = 'pending';

      if (displayData.status === 'completed') {
        status = 'completed';
      } else if (displayData.status === 'error' || displayData.status === 'failed') {
        status = stepIndex <= currentIndex ? 'error' : 'pending';
      } else if (stepIndex < currentIndex) {
        status = 'completed';
      } else if (stepIndex === currentIndex) {
        status = 'active';
      }

      return {
        id: stepId,
        label: config.label,
        icon: config.icon,
        status
      };
    });
  };

  const progressSteps = getProgressSteps();
  const isActive = !['completed', 'error', 'failed', 'cancelled'].includes(displayData.status || '');

  return (
    <Card className="relative overflow-hidden">
      {/* Header */}
      <div className="flex items-center gap-3 mb-4">
        <Badge color={crawlType.label.includes('Sitemap') ? 'purple' : 'blue'} variant="solid">
          {crawlType.icon}
          <span className="ml-1">{crawlType.label}</span>
        </Badge>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className={`
              ${statusConfig.color === 'green' ? 'text-green-600 dark:text-green-400' :
                statusConfig.color === 'red' ? 'text-red-600 dark:text-red-400' :
                statusConfig.color === 'blue' ? 'text-blue-600 dark:text-blue-400' :
                statusConfig.color === 'purple' ? 'text-purple-600 dark:text-purple-400' :
                statusConfig.color === 'orange' ? 'text-orange-600 dark:text-orange-400' :
                'text-gray-600 dark:text-gray-400'}
              font-medium
            `}>
              {statusConfig.label}
            </span>
            {isActive && (
              <motion.div
                animate={{ rotate: 360 }}
                transition={{ duration: 2, repeat: Infinity, ease: 'linear' }}
              >
                {statusConfig.icon}
              </motion.div>
            )}
          </div>
          {displayData.currentUrl && (
            <p className="text-sm text-gray-500 dark:text-zinc-400 truncate">
              {displayData.currentUrl}
            </p>
          )}
        </div>

        {/* Stop button */}
        {isActive && onStop && (
          <Button
            onClick={handleStop}
            disabled={isStopping}
            variant="ghost"
            size="sm"
            className="text-red-600 hover:text-red-700 dark:text-red-400"
          >
            <Square className="w-4 h-4" />
          </Button>
        )}
      </div>

