                          onChange={(value) => handleCornerChange('layer2', 'topLeft', value, layer2Linked, setLayer2Radius)}
                        />
                      </div>
                      <div className="flex items-center justify-between">
                        <span className="text-xs text-gray-600 dark:text-gray-400">TR</span>
                        <CornerInput
                          layer="layer2"
