import { useEffect, useMemo, useState } from 'react';
import { BarChart2, Play } from 'lucide-react';
import { MainLayout } from '../components/layout/MainLayout';
import { useToast } from '../features/ui/hooks/useToast';

type RAGEvalResult = {
  id?: string | number;
  content?: string;
  similarity?: number;
  similarity_score?: number;
  score?: number;
  metadata?: Record<string, any> | null;
};

type RAGEvalResponse = {
  results?: RAGEvalResult[];
  query: string;
  match_count?: number;
};

async function callRAG(query: string, k: number): Promise<RAGEvalResponse> {
  const res = await fetch('/api/rag/query', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ query, match_count: k }),
  });
  if (!res.ok) {
    let msg = `HTTP ${res.status}`;
    try {
      const data = await res.json();
      msg = data?.error || msg;
    } catch {
      void 0;
    }
    throw new Error(msg);
  }
  return res.json();
}

export function EvalPage() {
  const { showToast } = useToast();
  const [queriesText, setQueriesText] = useState('test\nembedding model\npydantic test model');
  const [k, setK] = useState<number>(10);
  const [running, setRunning] = useState(false);
  const [results, setResults] = useState<Record<string, { resp: RAGEvalResponse; durationMs: number; avgSim?: number; topSources?: Record<string, number> }>>({});
  const [presets, setPresets] = useState<Record<string, string>>({});
  const [presetName, setPresetName] = useState('');
  const [lastResults, setLastResults] = useState<Record<string, { resp: RAGEvalResponse; durationMs: number; avgSim?: number; topSources?: Record<string, number> }>>({});
  const [compareToLast, setCompareToLast] = useState(false);

  // Load persisted
  useEffect(() => {
    try {
      const savedQ = localStorage.getItem('rag_eval_queries');
      const savedK = localStorage.getItem('rag_eval_k');
      if (savedQ) setQueriesText(savedQ);
      if (savedK) setK(Number(savedK) || 10);
      const savedPresets = localStorage.getItem('rag_eval_presets');
      if (savedPresets) setPresets(JSON.parse(savedPresets));
      const savedLast = localStorage.getItem('rag_eval_last_results');
      if (savedLast) setLastResults(JSON.parse(savedLast));
    } catch {
      void 0;
    }
  }, []);

  // Persist
  useEffect(() => {
    try { localStorage.setItem('rag_eval_queries', queriesText); } catch { void 0; }
  }, [queriesText]);
  useEffect(() => {
    try { localStorage.setItem('rag_eval_k', String(k)); } catch { void 0; }
  }, [k]);

  const queries = useMemo(() => queriesText.split('\n').map(q => q.trim()).filter(Boolean), [queriesText]);

  const summary = useMemo(() => {
    const keys = Object.keys(results);
    if (keys.length === 0) return null;
    const sims = keys
      .map((k) => results[k]?.avgSim)
      .filter((v): v is number => typeof v === 'number');
    const min = sims.length ? Math.min(...sims) : undefined;
    const max = sims.length ? Math.max(...sims) : undefined;
    const avg = sims.length ? sims.reduce((a, b) => a + b, 0) / sims.length : undefined;
    const totalMs = keys.reduce((acc, k) => acc + (results[k]?.durationMs || 0), 0);
    return { count: keys.length, min, max, avg, totalMs };
  }, [results]);

  const onRun = async () => {
    if (queries.length === 0) {
      showToast('Add at least one query', 'warning');
      return;
    }
    setRunning(true);
    const out: Record<string, { resp: RAGEvalResponse; durationMs: number; avgSim?: number; topSources?: Record<string, number> }> = {};
    try {
      if (Object.keys(results).length > 0) {
        setLastResults(results);
        try { localStorage.setItem('rag_eval_last_results', JSON.stringify(results)); } catch { void 0; }
      }
      for (const q of queries) {
        try {
          const t0 = performance.now();
          const data = await callRAG(q, k);
          const t1 = performance.now();
          const items = (data?.results || []) as RAGEvalResult[];
          const sims = items
            .map(it => (typeof it.similarity === 'number' ? it.similarity : (typeof it.similarity_score === 'number' ? it.similarity_score : (typeof it.score === 'number' ? it.score : undefined))))
            .filter((v): v is number => typeof v === 'number');
          const avgSim = sims.length ? sims.reduce((a, b) => a + b, 0) / sims.length : undefined;
          const topSources: Record<string, number> = {};
          items.forEach(it => {
            const src = (it?.metadata?.source_id as string) || '';
            if (src) topSources[src] = (topSources[src] || 0) + 1;
          });
          out[q] = { resp: data, durationMs: t1 - t0, avgSim, topSources };
        } catch (e: any) {
          out[q] = { resp: { query: q, results: [], match_count: k }, durationMs: 0 };
          showToast(`RAG failed for "${q}": ${e?.message || e}`, 'error');
        }
      }
      setResults(out);
      showToast('Evaluation complete', 'success');
    } finally {
      setRunning(false);
    }
  };

  return (
    <MainLayout>
      <div className="max-w-6xl mx-auto w-full px-4 py-6">
        <div className="flex items-center gap-3 mb-6">
          <BarChart2 className="h-6 w-6 text-blue-500" />
          <h1 className="text-xl font-semibold">RAG Evaluation</h1>
        </div>

        <div className="rounded-xl border border-zinc-200 dark:border-zinc-800/50 p-4 bg-white/60 dark:bg-zinc-900/40 backdrop-blur mb-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs text-zinc-500 mb-1">Queries (one per line)</label>
              <textarea
                className="w-full h-32 rounded-lg bg-white/70 dark:bg-zinc-950/40 border border-zinc-200 dark:border-zinc-800 px-3 py-2"
                value={queriesText}
                onChange={(e) => setQueriesText(e.target.value)}
              />
              <div className="mt-1 text-[10px] text-zinc-500">Stored in localStorage for convenience.</div>
            </div>
            <div>
              <label className="block text-xs text-zinc-500 mb-1">Top K</label>
              <input
                type="number"
                min={1}
                max={50}
                className="w-28 rounded-lg bg-white/70 dark:bg-zinc-950/40 border border-zinc-200 dark:border-zinc-800 px-3 py-2"
                value={k}
                onChange={(e) => setK(Number(e.target.value) || 10)}
              />
              <div className="mt-4">
                <button
                  className="inline-flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-600 text-white hover:bg-blue-500 disabled:opacity-50"
                  onClick={onRun}
                  disabled={running}
                  title="Execute evaluation for all queries"
                >
                  <Play className="w-4 h-4" />
                  {running ? 'Running…' : 'Run'}
                </button>
              </div>
              <div className="mt-6 flex items-center gap-2 flex-wrap">
                <input
                  className="w-48 rounded-lg bg-white/70 dark:bg-zinc-950/40 border border-zinc-200 dark:border-zinc-800 px-3 py-2"
                  placeholder="Preset name"
                  value={presetName}
                  onChange={(e) => setPresetName(e.target.value)}
                  title="Save current queries as a preset"
                />
                <button
                  className="px-3 py-2 rounded-lg border border-zinc-300 dark:border-zinc-700 hover:bg-zinc-100/50 dark:hover:bg-zinc-800/30"
                  onClick={() => {
                    if (!presetName.trim()) { showToast('Enter a preset name', 'warning'); return; }
                    const next = { ...presets, [presetName.trim()]: queriesText };
                    setPresets(next);
                    try { localStorage.setItem('rag_eval_presets', JSON.stringify(next)); } catch { void 0; }
                    showToast('Preset saved', 'success');
                  }}
                >Save</button>
                {Object.keys(presets).length > 0 && (
                  <select
                    className="rounded-lg bg-white/70 dark:bg-zinc-950/40 border border-zinc-200 dark:border-zinc-800 px-3 py-2"
                    onChange={(e) => {
                      const key = e.target.value;
                      if (key && presets[key]) setQueriesText(presets[key]);
                    }}
                    defaultValue=""
                    title="Load preset"
                  >
                    <option value="" disabled>Load preset…</option>
                    {Object.keys(presets).map(name => (
                      <option key={name} value={name}>{name}</option>
                    ))}
                  </select>
                )}
                {Object.keys(presets).length > 0 && (
                  <button
                    className="px-3 py-2 rounded-lg border border-zinc-300 dark:border-zinc-700 hover:bg-zinc-100/50 dark:hover:bg-zinc-800/30"
                    onClick={() => {
                      if (!presetName.trim() || !presets[presetName.trim()]) { showToast('Select a saved preset name to delete', 'warning'); return; }
                      const next = { ...presets };
                      delete next[presetName.trim()];
                      setPresets(next);
                      try { localStorage.setItem('rag_eval_presets', JSON.stringify(next)); } catch { void 0; }
                      showToast('Preset deleted', 'success');
                    }}
                  >Delete</button>
                )}
                {Object.keys(results).length > 0 && (
                  <button
                    className="ml-2 px-3 py-2 rounded-lg border border-zinc-300 dark:border-zinc-700 hover:bg-zinc-100/50 dark:hover:bg-zinc-800/30"
                    onClick={() => {
                      try {
                        const payload = JSON.stringify(results, null, 2);
                        navigator.clipboard.writeText(payload);
                        showToast('Results copied to clipboard', 'success');
                      } catch (e: any) {
                        showToast(e?.message || 'Failed to copy', 'error');
                      }
                    }}
                    title="Copy JSON of results to clipboard"
                  >Copy JSON</button>
                )}
                <label className="ml-2 inline-flex items-center gap-2 text-xs text-zinc-600 dark:text-zinc-300">
                  <input type="checkbox" checked={compareToLast} onChange={(e) => setCompareToLast(e.target.checked)} />
                  Compare to last run
                </label>
                {Object.keys(lastResults).length > 0 && (
                  <>
                    <button
                      className="px-3 py-2 rounded-lg border border-zinc-300 dark:border-zinc-700 hover:bg-zinc-100/50 dark:hover:bg-zinc-800/30"
                      onClick={() => {
                        setLastResults(results);
                        try { localStorage.setItem('rag_eval_last_results', JSON.stringify(results)); } catch { void 0; }
                        showToast('Baseline updated to current results', 'success');
                      }}
                    >Set Baseline</button>
                    <button
                      className="px-3 py-2 rounded-lg border border-zinc-300 dark:border-zinc-700 hover:bg-zinc-100/50 dark:hover:bg-zinc-800/30"
                      onClick={() => {
                        setLastResults({});
                        try { localStorage.removeItem('rag_eval_last_results'); } catch { void 0; }
                        showToast('Baseline cleared', 'success');
                      }}
                    >Clear Baseline</button>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>

        {summary && (
          <div className="rounded-xl border border-zinc-200 dark:border-zinc-800/50 p-4 bg-white/60 dark:bg-zinc-900/40 backdrop-blur mb-4">
            <h2 className="text-lg font-medium mb-2">Summary</h2>
            <div className="grid grid-cols-2 md:grid-cols-5 gap-3 text-sm">
              <div>
                <div className="text-zinc-500 text-xs">Queries</div>
                <div className="font-medium">{summary.count}</div>
              </div>
              <div>
                <div className="text-zinc-500 text-xs">Avg sim</div>
                <div className="font-medium">{summary.avg !== undefined ? summary.avg.toFixed(3) : '—'}</div>
              </div>
              <div>
                <div className="text-zinc-500 text-xs">Min sim</div>
                <div className="font-medium">{summary.min !== undefined ? summary.min.toFixed(3) : '—'}</div>
              </div>
              <div>
                <div className="text-zinc-500 text-xs">Max sim</div>
                <div className="font-medium">{summary.max !== undefined ? summary.max.toFixed(3) : '—'}</div>
              </div>
              <div>
                <div className="text-zinc-500 text-xs">Total time</div>
                <div className="font-medium">{Math.round(summary.totalMs)} ms</div>
              </div>
            </div>
          </div>
        )}

        {Object.keys(results).length > 0 && (
          <div className="rounded-xl border border-zinc-200 dark:border-zinc-800/50 p-4 bg-white/60 dark:bg-zinc-900/40 backdrop-blur">
            <h2 className="text-lg font-medium mb-3">Results</h2>
            <div className="space-y-6">
              {queries.map((q) => {
                const entry = results[q];
                const prev = lastResults[q];
                const items = (entry?.resp?.results || []) as RAGEvalResult[];
                return (
                  <div key={q}>
                    <div className="flex items-center justify-between mb-2">
                      <div className="text-sm font-medium">Query: <span className="text-zinc-600 dark:text-zinc-300">{q}</span></div>
                      <div className="text-xs text-zinc-500">
                        {entry?.avgSim !== undefined && <span className="mr-3">avg sim: {entry.avgSim.toFixed(3)}</span>}
                        {entry?.durationMs !== undefined && <span>time: {Math.round(entry.durationMs)} ms</span>}
                        {compareToLast && prev?.avgSim !== undefined && entry?.avgSim !== undefined && (
                          <span className={`ml-3 ${entry.avgSim - (prev.avgSim||0) >= 0 ? 'text-emerald-600' : 'text-red-600'}`}>
                            Δ { (entry.avgSim - (prev.avgSim||0)).toFixed(3) }
                          </span>
                        )}
                      </div>
                    </div>
                    {items.length === 0 ? (
                      <div className="text-sm text-zinc-500">No results.</div>
                    ) : (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        {items.map((it, idx) => {
                          const sim = (typeof it.similarity === 'number') ? it.similarity : (typeof it.similarity_score === 'number') ? it.similarity_score : (typeof it.score === 'number') ? it.score : undefined;
                          const snippet = (it.content || '').slice(0, 160);
                          const src = it?.metadata?.source_id || (it as any)?.source || '';
                          return (
                            <div key={idx} className="rounded-lg border border-zinc-200 dark:border-zinc-800 p-3 bg-white/70 dark:bg-zinc-950/40">
                              <div className="text-xs text-zinc-500 mb-1">#{idx + 1} {src && <span>• {src}</span>}</div>
                              {sim !== undefined && (
                                <div className="text-xs text-emerald-600 dark:text-emerald-400 mb-1">sim: {sim.toFixed(3)}</div>
                              )}
                              <div className="text-sm whitespace-pre-wrap">{snippet}{snippet.length === 160 ? '…' : ''}</div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                    {compareToLast && prev?.topSources && entry?.topSources && (
                      <div className="mt-2 text-xs text-zinc-500">
                        Sources Δ:{' '}
                        {Object.keys({ ...(entry.topSources || {}), ...(prev.topSources || {}) })
                          .map((s) => s)
                          .sort()
                          .slice(0, 8)
                          .map((s, i) => {
                            const cur = (entry.topSources || {})[s] || 0;
                            const old = (prev.topSources || {})[s] || 0;
                            const diff = cur - old;
                            if (!diff) return null;
                            return (
                              <span key={s} className={diff > 0 ? 'text-emerald-600' : 'text-red-600'}>
                                {i > 0 ? ' • ' : ''}{s}:{diff > 0 ? `+${diff}` : diff}
                              </span>
                            );
                          })
                        }
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </MainLayout>
  );
}

export default EvalPage;

import { useEffect, useState, useMemo, lazy, Suspense } from 'react';
import { Search, Grid, Plus, Filter, BoxIcon, List, BookOpen, CheckSquare, Brain, Database } from 'lucide-react';
import { Link } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Card } from '../components/ui/Card';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';
import { useStaggeredEntrance } from '../hooks/useStaggeredEntrance';
import { useToast } from '../contexts/ToastContext';
import { knowledgeBaseService, KnowledgeItem, KnowledgeItemMetadata } from '../services/knowledgeBaseService';
import { CrawlProgressData } from '../types/crawl';
const KnowledgeTable = lazy(() => import('../components/knowledge-base/KnowledgeTable').then(m => ({ default: m.KnowledgeTable })));
const KnowledgeItemCard = lazy(() => import('../components/knowledge-base/KnowledgeItemCard').then(m => ({ default: m.KnowledgeItemCard })));
const GroupedKnowledgeItemCard = lazy(() => import('../components/knowledge-base/GroupedKnowledgeItemCard').then(m => ({ default: m.GroupedKnowledgeItemCard })));
import { KnowledgeGridSkeleton, KnowledgeTableSkeleton } from '../components/knowledge-base/KnowledgeItemSkeleton';
const GroupCreationModal = lazy(() => import('../components/knowledge-base/GroupCreationModal').then(m => ({ default: m.GroupCreationModal })));
const AddKnowledgeModal = lazy(() => import('../components/knowledge-base/AddKnowledgeModal').then(m => ({ default: m.AddKnowledgeModal })));
const CrawlingTab = lazy(() => import('../components/knowledge-base/CrawlingTab').then(m => ({ default: m.CrawlingTab })));
const DocumentBrowser = lazy(() => import('../components/knowledge-base/DocumentBrowser').then(m => ({ default: m.DocumentBrowser })));

interface GroupedKnowledgeItem {
  id: string;
  title: string;
  domain: string;
  items: KnowledgeItem[];
  metadata: KnowledgeItemMetadata;
  created_at: string;
  updated_at: string;
}

export const KnowledgeBasePage = () => {
  const [viewMode, setViewMode] = useState<'grid' | 'table'>('grid');
  const [searchQuery, setSearchQuery] = useState('');
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isGroupModalOpen, setIsGroupModalOpen] = useState(false);
  const [typeFilter, setTypeFilter] = useState<'all' | 'technical' | 'business'>('all');
  const [knowledgeItems, setKnowledgeItems] = useState<KnowledgeItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [_totalItems, setTotalItems] = useState(0);
  const [progressItems, setProgressItemsRaw] = useState<CrawlProgressData[]>([]);
  const [showCrawlingTab, setShowCrawlingTab] = useState(false);

  // Wrapper to ensure progress items are always unique
  const setProgressItems = (updater: CrawlProgressData[] | ((prev: CrawlProgressData[]) => CrawlProgressData[])) => {
    setProgressItemsRaw(prev => {
      const newItems = typeof updater === 'function' ? updater(prev) : updater;
      const itemMap = new Map(newItems.map(item => [item.progressId, item]));
      return Array.from(itemMap.values());
    });
  };

  // Selection state
  const [selectedItems, setSelectedItems] = useState<Set<string>>(new Set());
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [lastSelectedIndex, setLastSelectedIndex] = useState<number | null>(null);

  // Document browser state
  const [documentBrowserSourceId, setDocumentBrowserSourceId] = useState<string | null>(null);
  const [isDocumentBrowserOpen, setIsDocumentBrowserOpen] = useState(false);

  const { showToast } = useToast();

  // Load knowledge items
  const loadKnowledgeItems = async () => {
    try {
      setLoading(true);
      const response = await knowledgeBaseService.getKnowledgeItems({
        page: 1,
        per_page: 100
      });
      setKnowledgeItems(response.items);
      setTotalItems(response.total);
    } catch (error) {
      console.error('Failed to load knowledge items:', error);
      showToast('Failed to load knowledge items', 'error');
      setKnowledgeItems([]);
    } finally {
      setLoading(false);
    }
  };

  // Initialize on mount
  useEffect(() => {
    const timer = setTimeout(() => {
      loadKnowledgeItems();
    }, 100);

    return () => clearTimeout(timer);
  }, []);

  // Check for active progress on mount
  useEffect(() => {
    const activeCrawlsStr = localStorage.getItem('active_crawls');
    const activeCrawls = JSON.parse(activeCrawlsStr || '[]');

    if (activeCrawls.length > 0) {
      const restoredItems: CrawlProgressData[] = [];
      const staleItems: string[] = [];

      for (const crawlId of activeCrawls) {
        const crawlData = localStorage.getItem(`crawl_progress_${crawlId}`);

        if (crawlData) {
          try {
            const parsed = JSON.parse(crawlData);

            // Check if crawl is in a completed state or too old
            const isCompleted = ['completed', 'error', 'failed', 'cancelled'].includes(parsed.status);
            const now = Date.now();
            const startedAt = parsed.startedAt || now;
            const ageMinutes = (now - startedAt) / (1000 * 60);
            const isStale = ageMinutes > 5; // Clean up crawls older than 5 minutes on page refresh

            if (isCompleted || isStale) {
              staleItems.push(crawlId);
              console.log(`Removing ${isCompleted ? 'completed' : 'stale'} crawl: ${crawlId} (age: ${ageMinutes.toFixed(1)}min, status: ${parsed.status})`);
            } else {
              // Before restoring, verify the progress still exists on the server
              restoredItems.push({
                ...parsed,
                progressId: crawlId,
                _needsVerification: true // Flag for verification
              });
              console.log(`Queued for verification: ${crawlId} (age: ${ageMinutes.toFixed(1)}min, status: ${parsed.status})`);
            }
          } catch {
            staleItems.push(crawlId);
          }
        } else {
          staleItems.push(crawlId);
        }
      }

      // Clean up stale items
      if (staleItems.length > 0) {
        const updatedCrawls = activeCrawls.filter((id: string) => !staleItems.includes(id));
        localStorage.setItem('active_crawls', JSON.stringify(updatedCrawls));
        staleItems.forEach(id => {
          localStorage.removeItem(`crawl_progress_${id}`);
        });
      }

      // Verify and restore progress items
      if (restoredItems.length > 0) {
        setShowCrawlingTab(true);

        // Verify each item still exists on server
        verifyAndRestoreProgressItems(restoredItems);
      }
    }
  }, []);

  // Verify progress items still exist on server before restoring
  const verifyAndRestoreProgressItems = async (itemsToVerify: CrawlProgressData[]) => {
    const verifiedItems: CrawlProgressData[] = [];
    const itemsToRemove: string[] = [];

    for (const item of itemsToVerify) {
      try {
        // Try to fetch current progress from server
        const response = await fetch(`/api/progress/${item.progressId}`, {
          method: 'GET',
          credentials: 'include',
        });

        if (response.ok) {
          // Progress still exists, add to verified items
          verifiedItems.push(item);
          console.log(`Verified active progress: ${item.progressId}`);
        } else if (response.status === 404) {
          // Progress no longer exists, mark for removal
          itemsToRemove.push(item.progressId);
          console.log(`Progress no longer exists on server: ${item.progressId}`);
        }
      } catch (error) {
        // Network error or other issue, assume stale
        itemsToRemove.push(item.progressId);
        console.log(`Failed to verify progress (assuming stale): ${item.progressId}`);
      }
    }

    // Clean up items that no longer exist
    if (itemsToRemove.length > 0) {
      const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
      const updatedCrawls = activeCrawls.filter((id: string) => !itemsToRemove.includes(id));
      localStorage.setItem('active_crawls', JSON.stringify(updatedCrawls));

      itemsToRemove.forEach(id => {
        localStorage.removeItem(`crawl_progress_${id}`);
      });

      console.log(`Cleaned up ${itemsToRemove.length} stale progress items`);
    }

    // Set only verified items
    if (verifiedItems.length > 0) {
      setProgressItems(verifiedItems);
      console.log(`Restored ${verifiedItems.length} verified progress items`);
    } else {
      setShowCrawlingTab(false);
      console.log('No active progress items found after verification');
    }
  };

  // Note: Completion refresh is now handled immediately in handleProgressComplete

  // Filtered items
  const filteredItems = useMemo(() => {
    return knowledgeItems.filter(item => {
      const typeMatch = typeFilter === 'all' || item.metadata.knowledge_type === typeFilter;
      const searchLower = searchQuery.toLowerCase();
      const searchMatch = !searchQuery || 
        item.title.toLowerCase().includes(searchLower) ||
        item.metadata.description?.toLowerCase().includes(searchLower) ||
        item.metadata.tags?.some(tag => tag.toLowerCase().includes(searchLower)) ||
        item.source_id.toLowerCase().includes(searchLower);

      return typeMatch && searchMatch;
    });
  }, [knowledgeItems, typeFilter, searchQuery]);

  // Grouped items
  const groupedItems = useMemo(() => {
    if (viewMode !== 'grid') return [];

    return filteredItems
      .filter(item => item.metadata?.group_name)
      .reduce((groups: GroupedKnowledgeItem[], item) => {
        const groupName = item.metadata.group_name!;
        const existingGroup = groups.find(g => g.title === groupName);

        if (existingGroup) {
          existingGroup.items.push(item);
        } else {
          groups.push({
            id: `group_${groupName.replace(/\s+/g, '_')}`,
            title: groupName,
            domain: groupName,
            items: [item],
            metadata: {
              ...item.metadata,
              chunks_count: item.metadata.chunks_count || 0,
              word_count: item.metadata.word_count || 0,
            },
            created_at: item.created_at,
            updated_at: item.updated_at,
          });
        }

        return groups;
      }, []);
  }, [filteredItems, viewMode]);

  const ungroupedItems = useMemo(() => {
    return viewMode === 'grid' ? filteredItems.filter(item => !item.metadata?.group_name) : [];
  }, [filteredItems, viewMode]);

  // Animation variants
  const {
    containerVariants: headerContainerVariants,
    itemVariants: headerItemVariants,
    titleVariants
  } = useStaggeredEntrance([1, 2], 0.15);

  const {
    containerVariants: contentContainerVariants,
    itemVariants: contentItemVariants
  } = useStaggeredEntrance(filteredItems, 0.15);

  // Handlers
  const handleAddKnowledge = () => {
    setIsAddModalOpen(true);
  };

  const handleBrowseDocuments = (sourceId: string) => {
    setDocumentBrowserSourceId(sourceId);
    setIsDocumentBrowserOpen(true);
  };

  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    if (isSelectionMode) {
      setSelectedItems(new Set());
      setLastSelectedIndex(null);
    }
  };

  const toggleItemSelection = (itemId: string, index: number, event: React.MouseEvent) => {
    const newSelected = new Set(selectedItems);

    if (event.shiftKey && lastSelectedIndex !== null) {
      const start = Math.min(lastSelectedIndex, index);
      const end = Math.max(lastSelectedIndex, index);

      for (let i = start; i <= end; i++) {
        if (filteredItems[i]) {
          newSelected.add(filteredItems[i].id);
        }
      }
    } else if (event.ctrlKey || event.metaKey) {
      if (newSelected.has(itemId)) {
        newSelected.delete(itemId);
      } else {
        newSelected.add(itemId);
      }
    } else {
      if (newSelected.has(itemId)) {
        newSelected.delete(itemId);
      } else {
        newSelected.add(itemId);
      }
    }

    setSelectedItems(newSelected);
    setLastSelectedIndex(index);
  };

  const selectAll = () => {
    const allIds = new Set(filteredItems.map(item => item.id));
    setSelectedItems(allIds);
  };

  const deselectAll = () => {
    setSelectedItems(new Set());
    setLastSelectedIndex(null);
  };

  const deleteSelectedItems = async () => {
    if (selectedItems.size === 0) return;

    const count = selectedItems.size;
    // eslint-disable-next-line no-alert
    const confirmed = window.confirm(`Are you sure you want to delete ${count} selected item${count > 1 ? 's' : ''}?`);

    if (!confirmed) return;

    try {
      const deletePromises = Array.from(selectedItems).map(itemId => 
        knowledgeBaseService.deleteKnowledgeItem(itemId)
      );

      await Promise.all(deletePromises);

      setKnowledgeItems(prev => prev.filter(item => !selectedItems.has(item.id)));
      setSelectedItems(new Set());
      setIsSelectionMode(false);

      showToast(`Successfully deleted ${count} item${count > 1 ? 's' : ''}`, 'success');
    } catch (error) {
      console.error('Failed to delete selected items:', error);
      showToast('Failed to delete some items', 'error');
    }
  };

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'a' && isSelectionMode) {
        e.preventDefault();
        selectAll();
      }

      if (e.key === 'Escape' && isSelectionMode) {
        toggleSelectionMode();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSelectionMode, filteredItems]);

  const handleRefreshItem = async (sourceId: string) => {
    try {
      const item = knowledgeItems.find(k => k.source_id === sourceId);
      if (!item) return;

      const response = await knowledgeBaseService.refreshKnowledgeItem(sourceId);

      if (response.progressId) {
        const progressData: CrawlProgressData = {
          progressId: response.progressId,
          currentUrl: item.url,
          totalPages: 0,
          processedPages: 0,
          progress: 0,
          status: 'starting',
          message: 'Starting refresh...',
          crawlType: 'refresh',
          currentStep: 'starting',
          startTime: new Date()
        };

        setProgressItems(prev => [...prev, progressData]);
        setShowCrawlingTab(true);

        // Store in localStorage
        localStorage.setItem(`crawl_progress_${response.progressId}`, JSON.stringify({
          ...progressData,
          startedAt: Date.now()
        }));

        const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
        if (!activeCrawls.includes(response.progressId)) {
          activeCrawls.push(response.progressId);
          localStorage.setItem('active_crawls', JSON.stringify(activeCrawls));
        }

        setKnowledgeItems(prev => prev.filter(k => k.source_id !== sourceId));
      }
    } catch (error) {
      console.error('Failed to refresh knowledge item:', error);
      showToast('Failed to refresh knowledge item', 'error');
    }
  };

  const handleDeleteItem = async (sourceId: string) => {
    try {
      if (sourceId.startsWith('group_')) {
        const groupName = sourceId.replace('group_', '').replace(/_/g, ' ');
        const group = groupedItems.find(g => g.title === groupName);

        if (group) {
          const deletedIds: string[] = [];
          for (const item of group.items) {
            await knowledgeBaseService.deleteKnowledgeItem(item.source_id);
            deletedIds.push(item.source_id);
          }

          setKnowledgeItems(prev => prev.filter(item => !deletedIds.includes(item.source_id)));
          showToast(`Deleted ${group.items.length} items from group "${groupName}"`, 'success');
        }
      } else {
        const result = await knowledgeBaseService.deleteKnowledgeItem(sourceId);
        setKnowledgeItems(prev => prev.filter(item => item.source_id !== sourceId));
        showToast((result as any).message || 'Item deleted', 'success');
      }
    } catch (error) {
      console.error('Failed to delete item:', error);
      showToast('Failed to delete item', 'error');
    }
  };

  // Progress handling
  const handleProgressComplete = (data: CrawlProgressData) => {
    // Clean up localStorage immediately
    localStorage.removeItem(`crawl_progress_${data.progressId}`);
    const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
    const updated = activeCrawls.filter((id: string) => id !== data.progressId);
    localStorage.setItem('active_crawls', JSON.stringify(updated));

    // Show success message
    const message = data.uploadType === 'document' 
      ? `Document "${data.fileName}" uploaded successfully!`
      : `Crawling completed for ${data.currentUrl}!`;
    showToast(message, 'success');

    // Immediately remove progress card and refresh sources
    setProgressItems(prev => {
      const filtered = prev.filter(item => item.progressId !== data.progressId);
      // Hide crawling tab if this was the last item
      if (filtered.length === 0) {
        setShowCrawlingTab(false);
      }
      return filtered;
    });

    // Immediately refresh sources list to show the new completed source
    loadKnowledgeItems();
  };

  const handleProgressError = (error: string, progressId?: string) => {
    if (progressId) {
      setProgressItems(prev => prev.map(item => 
        item.progressId === progressId 
          ? { ...item, status: 'failed', error }
          : item
      ));

      localStorage.removeItem(`crawl_progress_${progressId}`);
      const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
      const updated = activeCrawls.filter((id: string) => id !== progressId);
      localStorage.setItem('active_crawls', JSON.stringify(updated));

      setTimeout(() => {
        setProgressItems(prev => prev.filter(item => item.progressId !== progressId));
        if (progressItems.length === 1) {
          setShowCrawlingTab(false);
        }
      }, 5000);
    }
    showToast(`Crawling failed: ${error}`, 'error');
  };

  const handleRetryProgress = async (progressId: string) => {
    const progressItem = progressItems.find(item => item.progressId === progressId);
    if (!progressItem) {
      showToast('Progress item not found', 'error');
      return;
    }

    try {
      setProgressItems(prev => prev.map(item => 
        item.progressId === progressId 
          ? { ...item, status: 'starting', error: undefined, message: 'Retrying...' }
          : item
      ));

      localStorage.removeItem(`crawl_progress_${progressId}`);
      const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
      const updated = activeCrawls.filter((id: string) => id !== progressId);
      localStorage.setItem('active_crawls', JSON.stringify(updated));

      if (progressItem.originalCrawlParams) {
        showToast('Retrying crawl...', 'info');
        const result = await knowledgeBaseService.crawlUrl(progressItem.originalCrawlParams);

        if ((result as any).progressId) {
          await handleStartCrawl((result as any).progressId, {
            currentUrl: progressItem.originalCrawlParams.url,
            totalPages: 0,
            processedPages: 0,
            originalCrawlParams: progressItem.originalCrawlParams
          });
          showToast('Crawl restarted successfully', 'success');
        }
      }
    } catch (error) {
      console.error('Failed to retry:', error);
      showToast('Retry failed', 'error');
    }
  };

  const handleStopProgress = async (progressId: string) => {
    try {
      await knowledgeBaseService.stopCrawl(progressId);

      setProgressItems(prev => prev.map(item => 
        item.progressId === progressId 
          ? { ...item, status: 'cancelled' }
          : item
      ));

      const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
      const updated = activeCrawls.filter((id: string) => id !== progressId);
      localStorage.setItem('active_crawls', JSON.stringify(updated));
    } catch (error) {
      console.error('Failed to stop crawl:', error);
      showToast('Failed to stop crawl', 'error');
    }
  };

  const handleDismissProgress = (progressId: string) => {
    setProgressItems(prev => prev.filter(item => item.progressId !== progressId));
    if (progressItems.length === 1) {
      setShowCrawlingTab(false);
    }

    localStorage.removeItem(`crawl_progress_${progressId}`);
    const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
    const updated = activeCrawls.filter((id: string) => id !== progressId);
    localStorage.setItem('active_crawls', JSON.stringify(updated));
  };

  const handleStartCrawl = async (progressId: string, initialData: Partial<CrawlProgressData>) => {
    const newProgressItem: CrawlProgressData = {
      ...initialData,
      progressId,
      status: 'starting',
      progress: 0,
      message: 'Starting crawl...'
    } as CrawlProgressData;

    setProgressItems(prev => [...prev, newProgressItem]);
    setShowCrawlingTab(true);

    localStorage.setItem(`crawl_progress_${progressId}`, JSON.stringify({
      ...newProgressItem,
      startedAt: Date.now()
    }));

    const activeCrawls = JSON.parse(localStorage.getItem('active_crawls') || '[]');
    if (!activeCrawls.includes(progressId)) {
      activeCrawls.push(progressId);
      localStorage.setItem('active_crawls', JSON.stringify(activeCrawls));
    }
  };

  return (
    <div>
      {/* Header */}
      <motion.div 
        className="flex justify-between items-center mb-8" 
        initial="hidden" 
        animate="visible" 
        variants={headerContainerVariants}
      >
        <motion.h1 
          className="text-3xl font-bold text-gray-800 dark:text-white flex items-center gap-3" 
          variants={titleVariants}
        >
          <BookOpen className="w-7 h-7 text-green-500 filter drop-shadow-[0_0_8px_rgba(34,197,94,0.8)]" />
          Knowledge Base
        </motion.h1>
        <motion.div className="flex items-center gap-4" variants={headerItemVariants}>
          <div className="relative">
            <Input 
              type="text" 
              value={searchQuery} 
              onChange={e => setSearchQuery(e.target.value)} 
              placeholder="Search knowledge base..." 
              accentColor="purple" 
              icon={<Search className="w-4 h-4" />} 
            />
          </div>

          <div className="flex items-center bg-gray-50 dark:bg-black border border-gray-200 dark:border-zinc-900 rounded-md overflow-hidden">
            <button 
              onClick={() => setTypeFilter('all')} 
              className={`p-2 ${typeFilter === 'all' ? 'bg-gray-200 dark:bg-zinc-800 text-gray-800 dark:text-white' : 'text-gray-500 dark:text-zinc-500 hover:text-gray-700 dark:hover:text-zinc-300'}`} 
              title="All Types"
            >
              <Filter className="w-4 h-4" />
            </button>
            <button 
              onClick={() => setTypeFilter('technical')} 
              className={`p-2 ${typeFilter === 'technical' ? 'bg-blue-100 dark:bg-blue-500/10 text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-zinc-500 hover:text-gray-700 dark:hover:text-zinc-300'}`} 
              title="Technical/Coding"
            >
              <BoxIcon className="w-4 h-4" />
            </button>
            <button 
              onClick={() => setTypeFilter('business')} 
              className={`p-2 ${typeFilter === 'business' ? 'bg-pink-100 dark:bg-pink-500/10 text-pink-600 dark:text-pink-400' : 'text-gray-500 dark:text-zinc-500 hover:text-gray-700 dark:hover:text-zinc-300'}`} 
              title="Business/Project"
            >
              <Brain className="w-4 h-4" />
            </button>
          </div>

          <div className="flex items-center bg-gray-50 dark:bg-black border border-gray-200 dark:border-zinc-900 rounded-md overflow-hidden">
            <button 
              onClick={() => setViewMode('grid')} 
              className={`p-2 ${viewMode === 'grid' ? 'bg-purple-100 dark:bg-purple-500/10 text-purple-600 dark:text-purple-500' : 'text-gray-500 dark:text-zinc-500 hover:text-gray-700 dark:hover:text-zinc-300'}`} 
              title="Grid View"
            >
              <Grid className="w-4 h-4" />
            </button>
            <button 
              onClick={() => setViewMode('table')} 
              className={`p-2 ${viewMode === 'table' ? 'bg-blue-100 dark:bg-blue-500/10 text-blue-600 dark:text-blue-500' : 'text-gray-500 dark:text-zinc-500 hover:text-gray-700 dark:hover:text-zinc-300'}`} 
