                  {ungroupedItems.map((item, index) => (
                    <motion.div key={item.id} variants={contentItemVariants}>
                      <KnowledgeItemCard 
                        item={item} 
                        onDelete={handleDeleteItem} 
                        onUpdate={loadKnowledgeItems} 
                        onRefresh={handleRefreshItem}
                        onBrowseDocuments={handleBrowseDocuments}
                        isSelectionMode={isSelectionMode}
                        isSelected={selectedItems.has(item.id)}
                        onToggleSelection={(e) => toggleItemSelection(item.id, index, e)}
                      />
                    </motion.div>
                  ))}

                  {groupedItems.length === 0 && ungroupedItems.length === 0 && (
                    <div className="col-span-full py-10 text-center text-gray-500 dark:text-zinc-400">
                      No knowledge items found for the selected filter.
                    </div>
                  )}
                </div>
              </Suspense>
            </motion.div>
          </AnimatePresence>
        )}
      </div>

      {/* Modals */}
      {isAddModalOpen && (
        <Suspense fallback={<div className="p-4 text-sm text-zinc-500">Loading…</div>}>
          <AddKnowledgeModal 
            onClose={() => setIsAddModalOpen(false)} 
            onSuccess={() => {
              loadKnowledgeItems();
              setIsAddModalOpen(false);
            }}
            onStartCrawl={handleStartCrawl}
          />
        </Suspense>
      )}

      {isGroupModalOpen && (
        <Suspense fallback={<div className="p-4 text-sm text-zinc-500">Loading…</div>}>
          <GroupCreationModal
            selectedItems={knowledgeItems.filter(item => selectedItems.has(item.id))}
            onClose={() => setIsGroupModalOpen(false)}
            onSuccess={() => {
              setIsGroupModalOpen(false);
              toggleSelectionMode();
              loadKnowledgeItems();
            }}
          />
        </Suspense>
      )}

      {/* Document Browser Modal */}
      {isDocumentBrowserOpen && documentBrowserSourceId && (
        <Suspense fallback={<div className="p-4 text-sm text-zinc-500">Loading documents…</div>}>
          <DocumentBrowser
            sourceId={documentBrowserSourceId}
            isOpen={isDocumentBrowserOpen}
            onClose={() => {
              setIsDocumentBrowserOpen(false);
              setDocumentBrowserSourceId(null);
            }}
          />
        </Suspense>
      )}
    </div>
  );
};

import { useState } from 'react';
import { McpViewWithBoundary } from '../features/mcp';

export const MCPPage = () => {
  const [initResult, setInitResult] = useState<string>('');
  const [infoResult, setInfoResult] = useState<string>('');

  const initSession = async () => {
    try {
      const res = await fetch('/api/mcp/session/init', { method: 'POST' });
      const txt = await res.text();
      // Pretty print JSON if possible
      try {
        const obj = JSON.parse(txt);
        setInitResult(JSON.stringify(obj, null, 2));
      } catch {
        setInitResult(txt);
      }
    } catch (e: any) {
      setInitResult(e?.message || 'Failed to init session');
    }
  };

  const getInfo = async () => {
    try {
      const res = await fetch('/api/mcp/session/info');
      const txt = await res.text();
      try {
        const obj = JSON.parse(txt);
        setInfoResult(JSON.stringify(obj, null, 2));
      } catch {
        setInfoResult(txt);
      }
    } catch (e: any) {
      setInfoResult(e?.message || 'Failed to get session info');
    }
  };

  return (
    <div className="flex flex-col gap-4">
      {/* Quick MCP Session Tools */}
      <div className="mx-4 mt-4 rounded-xl border border-zinc-200 dark:border-zinc-800/50 p-4 bg-white/60 dark:bg-zinc-900/40 backdrop-blur">
        <div className="flex items-center justify-between mb-2">
          <h2 className="text-sm font-medium text-zinc-700 dark:text-zinc-300">MCP Session Helpers</h2>
          <div className="flex items-center gap-2">
            <button className="px-3 py-1.5 rounded-lg bg-blue-600 text-white hover:bg-blue-500" onClick={initSession}>Init Session</button>
            <button className="px-3 py-1.5 rounded-lg bg-zinc-800 text-white hover:bg-zinc-700" onClick={getInfo}>Session Info</button>
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 text-xs">
          <div>
            <div className="text-zinc-500 mb-1">Init Response</div>
            <pre className="p-2 rounded bg-zinc-100 dark:bg-zinc-900 overflow-auto max-h-48 whitespace-pre-wrap">{initResult || '—'}</pre>
          </div>
          <div>
            <div className="text-zinc-500 mb-1">Session Info</div>
            <pre className="p-2 rounded bg-zinc-100 dark:bg-zinc-900 overflow-auto max-h-48 whitespace-pre-wrap">{infoResult || '—'}</pre>
          </div>
        </div>
      </div>

      {/* Existing MCP view */}
      <McpViewWithBoundary />
    </div>
  );
};

