/**
 * Agent Chat Service
 * Handles communication with AI agents via REST API
 */

import { serverHealthService } from './serverHealthService';

export interface ChatMessage {
  id: string;
  content: string;
  sender: 'user' | 'agent';
  timestamp: string | Date;
  agent_type?: string;
}

interface ChatSession {
  session_id: string;
  project_id?: string;
  messages: ChatMessage[];
  agent_type: string;
  created_at: Date;
}

interface ChatRequest {
  message: string;
  project_id?: string;
  context?: Record<string, any>;
  agentId?: string;
}

class AgentChatService {
  private baseUrl: string;
  private pollingIntervals: Map<string, NodeJS.Timeout> = new Map();
  private messageHandlers: Map<string, (message: ChatMessage) => void> = new Map();
  private errorHandlers: Map<string, (error: Error) => void> = new Map();
  private serverStatus: 'online' | 'offline' | 'unknown' = 'unknown';

  constructor() {
    // In development, the API is proxied through Vite, so we use the same origin
    // In production, this would be the actual API URL
    this.baseUrl = '';
  }

  /**
   * Clean up polling for a session
   */
  private cleanupConnection(sessionId: string): void {
    const interval = this.pollingIntervals.get(sessionId);
    if (interval) {
      clearInterval(interval);
      this.pollingIntervals.delete(sessionId);
    }

    this.messageHandlers.delete(sessionId);
    this.errorHandlers.delete(sessionId);
  }

  /**
   * Check if the chat server is online
   */
  private async checkServerStatus(): Promise<'online' | 'offline'> {
    try {
      const response = await fetch(`${this.baseUrl}/api/agent-chat/status`, {
        method: 'GET',
      });

      if (response.ok) {
        this.serverStatus = 'online';
        return 'online';
      } else {
        this.serverStatus = 'offline';
        return 'offline';
      }
    } catch (error) {
      console.error('Failed to check chat server status:', error);
      this.serverStatus = 'offline';
      return 'offline';
    }
  }

  /**
   * Validate a session exists
   */
  async validateSession(sessionId: string): Promise<boolean> {
    try {
      const response = await fetch(`${this.baseUrl}/api/agent-chat/sessions/${sessionId}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      return response.ok;
    } catch (error) {
      console.error('Failed to validate session:', error);
      return false;
    }
  }

  /**
   * Create or get an existing chat session
   */
  async createSession(agentType: string, projectId?: string): Promise<ChatSession> {
    try {
      const response = await fetch(`${this.baseUrl}/api/agent-chat/sessions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          agent_type: agentType,
          project_id: projectId
        }),
      });

      if (!response.ok) {
        // If we get a 404, the agent service is not running
        if (response.status === 404) {
          console.log('Agent chat service not available - service may be disabled');
          throw new Error('Agent chat service is not available. The service may be disabled.');
        }
        throw new Error(`Failed to create session: ${response.statusText}`);
      }

      const session = await response.json();
      return session;
    } catch (error) {
      // Don't log fetch errors for disabled service
      if (error instanceof Error && !error.message.includes('not available')) {
        console.error('Failed to create chat session:', error);
      }
      throw error;
    }
  }

  /**
   * Send a message to an existing chat session
   */
  async sendMessage(sessionId: string, request: ChatRequest): Promise<ChatMessage> {
    try {
      const response = await fetch(`${this.baseUrl}/api/agent-chat/sessions/${sessionId}/send`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(request),
      });

      if (!response.ok) {
        throw new Error(`Failed to send message: ${response.statusText}`);
      }

      const message = await response.json();
      return message;
    } catch (error) {
      console.error('Failed to send message:', error);
      throw error;
    }
  }

  /**
   * Stream messages from a chat session using polling
   */
  async streamMessages(
    sessionId: string,
    onMessage: (message: ChatMessage) => void,
    onError?: (error: Error) => void
  ): Promise<void> {
    // Store handlers
    this.messageHandlers.set(sessionId, onMessage);
    if (onError) {
      this.errorHandlers.set(sessionId, onError);
    }

    // Start polling for new messages
    let lastMessageId: string | null = null;

    const pollInterval = setInterval(async () => {
      try {
        const response = await fetch(`${this.baseUrl}/api/agent-chat/sessions/${sessionId}/messages${lastMessageId ? `?after=${lastMessageId}` : ''}`, {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
          },
        });

        if (!response.ok) {
          // If we get a 404, the service is not available - stop polling
          if (response.status === 404) {
            console.log('Agent chat service not available (404) - stopping polling');
            clearInterval(pollInterval);
            this.pollingIntervals.delete(sessionId);
            const errorHandler = this.errorHandlers.get(sessionId);
            if (errorHandler) {
              errorHandler(new Error('Agent chat service is not available'));
            }
            return;
          }
          throw new Error(`Failed to fetch messages: ${response.statusText}`);
        }

        const messages: ChatMessage[] = await response.json();

        // Process new messages (only if we have new ones)
        if (messages.length > 0) {
          for (const message of messages) {
            // Only process if this is actually a new message
            if (!lastMessageId || message.id !== lastMessageId) {
              lastMessageId = message.id;
              const handler = this.messageHandlers.get(sessionId);
              if (handler) {
                handler(message);
              }
            }
          }
        }
      } catch (error) {
        // Only log non-404 errors (404s are handled above)
        if (error instanceof Error && !error.message.includes('404')) {
          console.error('Failed to poll messages:', error);
        }
        const errorHandler = this.errorHandlers.get(sessionId);
        if (errorHandler) {
          errorHandler(error instanceof Error ? error : new Error('Unknown error'));
        }
      }
    }, 1000); // Poll every second

    this.pollingIntervals.set(sessionId, pollInterval);
  }

  /**
   * Stop streaming messages from a session
   */
  stopStreaming(sessionId: string): void {
    this.cleanupConnection(sessionId);
  }

  /**
   * Get chat history for a session
   */
  async getChatHistory(sessionId: string): Promise<ChatMessage[]> {
    try {
      const response = await fetch(`${this.baseUrl}/api/agent-chat/sessions/${sessionId}/messages`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to get chat history: ${response.statusText}`);
      }

      const messages = await response.json();
      return messages;
    } catch (error) {
      console.error('Failed to get chat history:', error);
      throw error;
    }
  }

  /**
   * Delete a chat session
   */
  async deleteSession(sessionId: string): Promise<void> {
    try {
      // Clean up any active connections first
      this.cleanupConnection(sessionId);

      const response = await fetch(`${this.baseUrl}/api/agent-chat/sessions/${sessionId}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`Failed to delete session: ${response.statusText}`);
      }
    } catch (error) {
      console.error('Failed to delete chat session:', error);
      throw error;
    }
  }

  /**
   * Get server status
   */
  async getServerStatus(): Promise<'online' | 'offline' | 'unknown'> {
    const serverHealthy = await serverHealthService.isHealthy();
    if (!serverHealthy) {
      this.serverStatus = 'offline';
      return 'offline';
    }

    return this.checkServerStatus();
  }

  /**
   * Clean up all connections
   */
  cleanup(): void {
    // Clean up all active polling
    this.pollingIntervals.forEach((interval) => {
      clearInterval(interval);
    });
    this.pollingIntervals.clear();
    this.messageHandlers.clear();
    this.errorHandlers.clear();
  }
}

export const agentChatService = new AgentChatService();

/**
 * Bug Report Service for Archon Beta
 * 
 * Handles automatic context collection and GitHub issue creation for bug reports.
 */

import { getApiUrl } from '../config/api';

export interface BugContext {
  error: {
    message: string;
    stack?: string;
    name: string;
  };
  app: {
    version: string;
    url: string;
    timestamp: string;
  };
  system: {
    platform: string;
    userAgent: string;
    memory?: string;
  };
  services: {
    server: boolean;
    mcp: boolean;
    agents: boolean;
  };
  logs: string[];
}

export interface BugReportData {
  title: string;
  description: string;
  stepsToReproduce: string;
  expectedBehavior: string;
  actualBehavior: string;
  severity: 'low' | 'medium' | 'high' | 'critical';
  component: string;
  context: BugContext;
}

class BugReportService {
  /**
   * Collect automatic context information for bug reports
   */
  async collectBugContext(error?: Error): Promise<BugContext> {
    const context: BugContext = {
      error: {
        message: error?.message || 'Manual bug report',
        stack: error?.stack,
        name: error?.name || 'UserReportedError'
      },

      app: {
        version: await this.getVersion(),
        url: window.location.href,
        timestamp: new Date().toISOString()
      },

      system: {
        platform: navigator.platform,
        userAgent: navigator.userAgent,
        memory: this.getMemoryInfo()
      },

      services: await this.quickHealthCheck(),

      logs: await this.getRecentLogs(20)
    };

    return context;
  }

  /**
   * Get the current Archon version
   */
  private async getVersion(): Promise<string> {
    try {
      // Try to get version from main health endpoint
      const response = await fetch('/api/system/version');
      if (response.ok) {
        const data = await response.json();
        return data.version || 'v0.1.0';
      }
    } catch {
      // Fallback to default version
    }
    return 'v0.1.0';
  }

  /**
   * Get memory information if available
   */
  private getMemoryInfo(): string {
    try {
      const memory = (performance as any).memory;
      if (memory) {
        return `${Math.round(memory.usedJSHeapSize / 1024 / 1024)}MB used`;
      }
    } catch {
      // Memory API not available
    }
    return 'unknown';
  }

  /**
   * Quick health check of Archon services
   */
  private async quickHealthCheck(): Promise<{ server: boolean; mcp: boolean; agents: boolean; }> {
    const services = { server: false, mcp: false, agents: false };

    try {
      // Check services with a short timeout
      const checks = await Promise.allSettled([
        fetch('/api/health', { signal: AbortSignal.timeout(2000) }),
        fetch('/api/mcp/health', { signal: AbortSignal.timeout(2000) }),
        fetch('/api/agents/health', { signal: AbortSignal.timeout(2000) })
      ]);

      services.server = checks[0].status === 'fulfilled' && (checks[0].value as Response).ok;
      services.mcp = checks[1].status === 'fulfilled' && (checks[1].value as Response).ok;
      services.agents = checks[2].status === 'fulfilled' && (checks[2].value as Response).ok;
    } catch {
      // Health checks failed - services will remain false
    }

    return services;
  }

  /**
   * Get recent logs from browser console
   */
  private async getRecentLogs(_limit: number): Promise<string[]> {
    // This is a simplified version - in a real implementation,
    // you'd want to capture console logs proactively
    return [
      `[${new Date().toISOString()}] Browser logs not captured - consider implementing console log capture`,
      `[${new Date().toISOString()}] To get server logs, check Docker container logs`,
      `[${new Date().toISOString()}] Current URL: ${window.location.href}`,
      `[${new Date().toISOString()}] User Agent: ${navigator.userAgent}`
    ];
  }

  /**
   * Submit bug report to GitHub via backend API
   * Handles both direct API creation (maintainers) and manual submission URLs (open source users)
   */
  async submitBugReport(bugReport: BugReportData): Promise<{ success: boolean; issueUrl?: string; issueNumber?: number; message?: string; error?: string }> {
    try {
      // Format the request to match backend API expectations
      const requestData = {
        title: bugReport.title,
        description: bugReport.description,
        stepsToReproduce: bugReport.stepsToReproduce,
        expectedBehavior: bugReport.expectedBehavior,
        actualBehavior: bugReport.actualBehavior,
        severity: bugReport.severity,
        component: bugReport.component,
        context: bugReport.context
      };

      const response = await fetch(`${getApiUrl()}/api/bug-report/github`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestData),
      });

      if (response.ok) {
        const result = await response.json();
        return {
          success: result.success,
          issueUrl: result.issue_url,
          issueNumber: result.issue_number,
          message: result.message
        };
      } else {
        const errorText = await response.text();
        return {
          success: false,
          error: `Failed to create issue: ${errorText}`
        };
      }
    } catch (error) {
      return {
        success: false,
        error: `Network error: ${error instanceof Error ? error.message : 'Unknown error'}`
      };
    }
  }

  /**
   * Format bug report for clipboard as fallback
   */
  formatReportForClipboard(bugReport: BugReportData): string {
    return `
# 🐛 Bug Report

**Version:** ${bugReport.context.app.version}
**Severity:** ${bugReport.severity}
**Component:** ${bugReport.component}
**Platform:** ${bugReport.context.system.platform}

## Description
${bugReport.description}

## Steps to Reproduce
${bugReport.stepsToReproduce}

## Expected Behavior
${bugReport.expectedBehavior}

## Actual Behavior
${bugReport.actualBehavior}

## Error Details
\`\`\`
Error: ${bugReport.context.error.name}
Message: ${bugReport.context.error.message}

${bugReport.context.error.stack || 'No stack trace available'}
\`\`\`

## System Info
- **Platform:** ${bugReport.context.system.platform}
- **URL:** ${bugReport.context.app.url}
- **Timestamp:** ${bugReport.context.app.timestamp}
- **Memory:** ${bugReport.context.system.memory}

## Service Status
- **Server:** ${bugReport.context.services.server ? '✅' : '❌'}
- **MCP:** ${bugReport.context.services.mcp ? '✅' : '❌'}
- **Agents:** ${bugReport.context.services.agents ? '✅' : '❌'}

---
*Generated by Archon Bug Reporter*
    `.trim();
  }
}

